window.QB_TKP_B9 = [
{id:"TKP-1261", q:"Seorang petani lanjut usia datang ke kantor desa untuk meminta surat keterangan tidak mampu sebagai syarat beasiswa cucunya, tetapi ia lupa membawa KK karena rumahnya jauh. Tindakan yang paling tepat adalah ....", opts:[{t:"Memverifikasi datanya melalui buku induk kependudukan desa, menerbitkan suratnya, dan memintanya membawa KK saat mengambil surat", s:5},{t:"Memintanya pulang mengambil KK terlebih dahulu lalu kembali lagi ke kantor desa", s:4},{t:"Mencatat keperluannya dan memintanya kembali besok dengan berkas lengkap", s:3},{t:"Menolak melayani karena syarat administrasi tidak lengkap", s:2},{t:"Menyuruhnya mengurus ke kecamatan saja agar tidak merepotkan", s:1}], ex:"Pelayanan prima memanfaatkan data yang sudah dimiliki desa agar warga tidak bolak-balik, terutama kelompok rentan seperti lansia."},
{id:"TKP-1262", q:"Seorang ibu hamil dari dusun terpencil datang jauh-jauh ke kantor desa untuk mengurus KK baru, padahal satu dokumen persyaratannya kurang. Sikap terbaik Anda adalah ....", opts:[{t:"Membantu melengkapi kekurangan lewat koordinasi dengan RT/RW setempat via telepon, lalu memproses permohonannya hari itu juga", s:5},{t:"Memberikan daftar persyaratan tertulis dan memintanya kembali lagi setelah lengkap", s:4},{t:"Memintanya menunggu hingga ada petugas yang bisa menjelaskan", s:3},{t:"Menyuruhnya pulang dan kembali lain waktu karena berkas kurang", s:2},{t:"Menolak dengan alasan aturan tidak bisa ditawar", s:1}], ex:"Orientasi pelayanan berarti proaktif mengatasi kendala warga, apalagi yang menempuh jarak jauh, tanpa melanggar ketentuan."},
{id:"TKP-1263", q:"Kantor desa Anda tidak ramah bagi penyandang disabilitas pengguna kursi roda karena tangganya curam dan tidak ada bidang miring. Seorang warga disabilitas ingin mengurus surat domisili. Yang paling tepat adalah ....", opts:[{t:"Turun menemuinya di halaman kantor, melayani di sana, dan mengusulkan pembangunan jalur landai pada musyawarah desa", s:5},{t:"Meminta keluarganya membantu mengangkat kursi rodanya ke dalam kantor", s:4},{t:"Memintanya menunggu di luar sementara berkasnya dibawa masuk", s:3},{t:"Menyuruhnya mengutus orang lain saja lain kali", s:2},{t:"Menolak melayani dengan alasan fasilitas tidak memadai", s:1}], ex:"Pelayanan inklusif menuntut petugas mendatangi warga yang terkendala akses sekaligus mengupayakan perbaikan fasilitas."},
{id:"TKP-1264", q:"Menjelang jam tutup layanan, seorang warga dari dusun seberang sungai datang tergesa-gesa membutuhkan surat pengantar KTP-el yang rusak untuk keperluan berobat besok pagi. Keputusan Anda adalah ....", opts:[{t:"Tetap memproses suratnya hingga selesai karena kebutuhannya mendesak dan ia datang dari jauh", s:5},{t:"Memintanya datang lebih pagi besok agar dilayani pertama", s:4},{t:"Mencatat keperluannya dan berjanji memproses besok pagi", s:3},{t:"Menolak karena sudah melewati jam layanan", s:2},{t:"Menyuruhnya langsung ke dinas dukcapil kabupaten", s:1}], ex:"Pelayanan publik yang berorientasi pada kebutuhan warga mengutamakan penyelesaian kasus mendesak, bukan kekakuan jam kerja."},
{id:"TKP-1265", q:"Listrik padam dan sistem administrasi desa tidak bisa diakses, sementara belasan warga sudah antre membutuhkan berbagai surat. Tindakan terbaik adalah ....", opts:[{t:"Melayani secara manual dengan formulir kertas dan buku register, lalu menginput ke sistem setelah listrik menyala", s:5},{t:"Meminta warga menunggu hingga listrik menyala kembali", s:4},{t:"Melayani sebagian warga yang keperluannya paling mendesak saja", s:3},{t:"Membubarkan antrean dan meminta warga kembali besok", s:2},{t:"Menutup kantor lebih awal karena sistem tidak bisa dipakai", s:1}], ex:"Petugas yang adaptif tetap memberi layanan dengan cara manual saat sistem terganggu, bukan menghentikan pelayanan."},
{id:"TKP-1266", q:"Pada musrenbang desa, seorang warga mengusulkan perbaikan jalan tani yang rusak parah, tetapi usulan itu tidak masuk prioritas perangkat desa. Sebagai fasilitator, sikap Anda adalah ....", opts:[{t:"Mencatat usulan tersebut secara resmi, memasukkannya dalam daftar usulan prioritas, dan menjelaskan mekanisme penentuan skala prioritas secara transparan", s:5},{t:"Menampung usulannya dan berjanji akan dibahas perangkat desa kemudian", s:4},{t:"Memintanya mengajukan usulan tertulis saja ke kantor desa", s:3},{t:"Mengabaikan usulan itu karena tidak sesuai prioritas", s:2},{t:"Menegurnya karena dianggap mengganggu jalannya musyawarah", s:1}], ex:"Musyawarah desa harus menampung seluruh aspirasi warga secara tercatat dan transparan, sekalipun belum menjadi prioritas."},
{id:"TKP-1267", q:"Seorang warga mempertanyakan alokasi dana desa yang menurutnya tidak transparan karena papan informasi APBDes di balai desa sudah lama tidak diperbarui. Respons terbaik Anda adalah ....", opts:[{t:"Menjelaskan rincian penggunaan dana desa sesuai dokumen APBDes, memperbarui papan informasi, dan mempersilakan warga melihat dokumennya", s:5},{t:"Menjelaskan secara umum bahwa dana desa sudah digunakan sesuai rencana", s:4},{t:"Memintanya bertanya langsung kepada kepala desa", s:3},{t:"Menyatakan bahwa itu urusan internal perangkat desa", s:2},{t:"Menuduhnya tidak percaya kepada pemerintah desa", s:1}], ex:"Akuntabilitas mewajibkan keterbukaan informasi anggaran kepada publik; papan APBDes adalah sarana transparansi yang harus selalu mutakhir."},
{id:"TKP-1268", q:"Anda mendapati seorang calo menawarkan jasa mempercepat pengurusan surat-surat di kantor desa dengan imbalan uang kepada warga yang antre. Tindakan Anda adalah ....", opts:[{t:"Menegur dan menghentikan praktik calo tersebut, melaporkan ke kepala desa, serta mengingatkan warga agar mengurus langsung tanpa perantara", s:5},{t:"Memperingatkan calo tersebut agar tidak beroperasi di area kantor desa", s:4},{t:"Membiarkannya karena warga yang memakai jasanya melakukannya sukarela", s:3},{t:"Ikut menawarkan jasa serupa dengan tarif lebih murah", s:2},{t:"Meminta bagian dari keuntungan calo tersebut", s:1}], ex:"Pungli dalam bentuk apa pun merusak integritas pelayanan; petugas wajib menghentikannya dan melindungi warga."},
{id:"TKP-1269", q:"Program perekaman KTP-el keliling akan dilaksanakan di dusun terpencil, tetapi partisipasi diperkirakan rendah karena bertepatan dengan musim panen. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Berkordinasi dengan kepala dusun dan RT untuk mengatur jadwal bergiliran per kelompok tani agar panen dan perekaman sama-sama jalan", s:5},{t:"Tetap melaksanakan sesuai jadwal dan berharap warga datang di sela waktu panen", s:4},{t:"Menunda kegiatan hingga musim panen selesai", s:3},{t:"Melaksanakan kegiatan apa adanya tanpa sosialisasi tambahan", s:2},{t:"Membatalkan kegiatan dan melaporkan warga tidak kooperatif", s:1}], ex:"Pelayanan jemput bola yang efektif menyesuaikan dengan ritme kehidupan warga, bukan memaksa warga menyesuaikan jadwal dinas."},
{id:"TKP-1270", q:"Seorang warga membutuhkan surat keterangan kematian ayahnya untuk mengurus ahli waris, tetapi ia sangat terpukul dan tidak fokus menjelaskan keperluannya. Sikap Anda adalah ....", opts:[{t:"Menenangkannya dengan empati, membantunya menyebutkan data yang diperlukan satu per satu, dan menerbitkan suratnya segera", s:5},{t:"Memintanya tenang terlebih dahulu lalu menjelaskan persyaratan dengan sabar", s:4},{t:"Memberikan formulir dan memintanya mengisinya sendiri", s:3},{t:"Memintanya kembali lagi setelah lebih tenang", s:2},{t:"Menegurnya karena tidak bisa menjelaskan keperluan dengan jelas", s:1}], ex:"Empati dan keramahan adalah inti pelayanan publik, terutama bagi warga yang sedang berduka."},
{id:"TKP-1271", q:"Seorang pelaku UMKM desa ingin mengurus surat keterangan domisili usaha untuk mengajukan kredit usaha rakyat, tetapi ia tidak tahu prosedurnya sama sekali. Anda akan ....", opts:[{t:"Menjelaskan alur dan syaratnya langkah demi langkah, membantu menyiapkan berkasnya, dan menerbitkan suratnya hari itu juga bila syarat terpenuhi", s:5},{t:"Memberikan brosur persyaratan dan memintanya melengkapi sendiri", s:4},{t:"Mengarahkannya bertanya ke petugas lain yang lebih paham", s:3},{t:"Memintanya datang lagi setelah mencari tahu prosedurnya sendiri", s:2},{t:"Menolak membantu karena bukan tugas Anda menjelaskan", s:1}], ex:"Pelayanan yang berorientasi pada warga berarti aktif memandu, bukan sekadar memberi syarat, apalagi untuk pemberdayaan ekonomi desa."},
{id:"TKP-1272", q:"Sejumlah warga protes karena merasa tidak menerima Bantuan Langsung Tunai Dana Desa (BLT-DD) padahal merasa berhak. Mereka datang beramai-ramai ke kantor desa. Tindakan terbaik adalah ....", opts:[{t:"Menerima mereka dengan tenang, menjelaskan kriteria penerima sesuai aturan, membuka data penerima untuk diverifikasi bersama, dan menampung usulan perbaikan data", s:5},{t:"Menjelaskan kriteria penerima dan meminta mereka mengajukan keberatan tertulis", s:4},{t:"Meminta mereka bubar dan kembali setelah ada pemberitahuan resmi", s:3},{t:"Menutup pintu kantor dan menghindari mereka", s:2},{t:"Menuduh mereka diprovokasi pihak tertentu", s:1}], ex:"Transparansi data dan dialog terbuka adalah cara terbaik meredam protes sekaligus menjaga akuntabilitas penyaluran bantuan."},
{id:"TKP-1273", q:"Saat pembagian bantuan sosial di balai desa, antrean membludak dan tidak tertib hingga ada warga lansia yang terhimpit. Anda sebagai perangkat desa akan ....", opts:[{t:"Segera menata ulang antrean dengan jalur khusus lansia, ibu hamil, dan disabilitas, dibantu RT/RW dan karang taruna", s:5},{t:"Meminta warga antre dengan tertib melalui pengeras suara", s:4},{t:"Melanjutkan pembagian apa adanya agar cepat selesai", s:3},{t:"Menghentikan pembagian dan meminta warga pulang", s:2},{t:"Menyalahkan warga yang tidak bisa antre tertib", s:1}], ex:"Keselamatan dan kenyamanan warga prioritas; penataan antrean dengan jalur khusus kelompok rentan menunjukkan pelayanan prima."},
{id:"TKP-1274", q:"Seorang warga buta huruf ingin mengisi formulir permohonan KK baru tetapi malu mengakuinya di depan warga lain. Sikap Anda adalah ....", opts:[{t:"Mengajaknya ke ruang yang lebih privat, membacakan dan mengisikan formulirnya dengan sabar tanpa mempermalukannya", s:5},{t:"Membacakan formulirnya di loket dan membantu mengisinya", s:4},{t:"Memintanya meminta bantuan keluarganya mengisi formulir", s:3},{t:"Memberikan formulir dan menyuruhnya belajar mengisi sendiri", s:2},{t:"Menertawakannya di depan warga lain", s:1}], ex:"Menjaga martabat warga sambil membantu mengatasi keterbatasannya adalah wujud empati dalam pelayanan publik."},
{id:"TKP-1275", q:"Warga mengeluhkan jalan desa yang rusak parah dan berdebu, meminta perbaikan segera. Dana desa tahun ini sudah dialokasikan untuk program lain. Respons terbaik adalah ....", opts:[{t:"Menjelaskan alokasi anggaran yang sudah ditetapkan, mencatat keluhan sebagai usulan prioritas musrenbang berikutnya, dan mengupayakan perbaikan darurat swadaya bersama warga", s:5},{t:"Menjelaskan bahwa anggaran sudah habis dan meminta warga bersabar", s:4},{t:"Meminta warga mengajukan proposal tertulis ke kecamatan", s:3},{t:"Mengabaikan keluhan karena bukan prioritas tahun ini", s:2},{t:"Menyalahkan warga yang tidak mengusulkan saat musrenbang", s:1}], ex:"Keluhan warga harus ditampung resmi dan dicarikan solusi sementara yang realistis, bukan ditolak mentah-mentah."},
{id:"TKP-1276", q:"Jadwal layanan keliling administrasi ke dusun-dusun bentrok dengan jadwal pasar mingguan sehingga warga memilih ke pasar. Keputusan Anda adalah ....", opts:[{t:"Menggeser jadwal layanan keliling ke hari non-pasar setelah berkoordinasi dengan kepala dusun agar partisipasi maksimal", s:5},{t:"Tetap melaksanakan sesuai jadwal awal", s:4},{t:"Menggabungkan layanan keliling dengan kegiatan di pasar", s:3},{t:"Membatalkan layanan keliling bulan ini", s:2},{t:"Melaporkan warga dusun tidak antusias pada layanan", s:1}], ex:"Penjadwalan layanan harus adaptif terhadap aktivitas warga agar tepat sasaran, bukan kaku pada rencana awal."},
{id:"TKP-1277", q:"Seorang pemuda desa membutuhkan surat pengantar SKCK untuk melamar pekerjaan di kota, tetapi ia tidak membawa fotokopi KTP. Anda akan ....", opts:[{t:"Membuatkan fotokopi dari arsip data kependudukan desa, menerbitkan surat pengantarnya, dan mengingatkannya membawa fotokopi di kemudian hari", s:5},{t:"Memintanya memfotokopi KTP di tempat fotokopi terdekat lalu kembali", s:4},{t:"Memintanya kembali besok dengan fotokopi KTP", s:3},{t:"Menolak menerbitkan surat pengantar karena syarat kurang", s:2},{t:"Menyuruhnya mengurus langsung ke polsek tanpa pengantar", s:1}], ex:"Memanfaatkan arsip desa untuk mengatasi kekurangan kecil menunjukkan pelayanan yang solutif tanpa melanggar aturan."},
{id:"TKP-1278", q:"Ditemukan data ganda penerima bantuan pangan di desa Anda sehingga sebagian warga menerima dua kali. Sebagai perangkat desa yang mengetahuinya, Anda akan ....", opts:[{t:"Melaporkan temuan ke kepala desa, memverifikasi ulang data bersama RT/RW, dan mengembalikan kelebihan ke mekanisme yang benar", s:5},{t:"Memperbaiki data diam-diam agar tidak menimbulkan kegaduhan", s:4},{t:"Membiarkannya karena bukan Anda yang mendata", s:3},{t:"Memanfaatkan data ganda untuk kerabat Anda", s:2},{t:"Menutup-nutupi temuan agar desa tidak dinilai buruk", s:1}], ex:"Integritas menuntut temuan kesalahan data ditindaklanjuti secara terbuka dan benar, bukan disembunyikan."},
{id:"TKP-1279", q:"Seorang warga menyelipkan uang ke dalam berkas permohonannya agar suratnya diproses lebih cepat. Reaksi Anda adalah ....", opts:[{t:"Menolak dengan sopan, mengembalikan uangnya, menjelaskan bahwa semua dilayani sesuai antrean, dan tetap memproses permohonannya", s:5},{t:"Menolak uangnya dan memintanya antre seperti biasa", s:4},{t:"Mengambil uangnya tetapi tetap melayani sesuai antrean", s:3},{t:"Menerima uangnya dan memproses lebih cepat", s:2},{t:"Menerima uangnya lalu mengabaikan permohonannya", s:1}], ex:"Menolak gratifikasi secara tegas namun sopan sambil tetap melayani dengan baik adalah standar integritas ASN."},
{id:"TKP-1280", q:"Perpustakaan desa sepi pengunjung karena koleksi bukunya usang dan jam bukanya bersamaan dengan jam sekolah. Sebagai perangkat desa, Anda mengusulkan ....", opts:[{t:"Menambah koleksi buku anak dan remaja, menggeser jam buka ke sore hari, dan mengadakan pojok baca keliling ke dusun-dusun", s:5},{t:"Mengusulkan pengadaan buku baru pada anggaran tahun depan", s:4},{t:"Membiarkan perpustakaan apa adanya karena minat baca rendah", s:3},{t:"Menutup perpustakaan dan mengalihfungsikan ruangannya", s:2},{t:"Menyalahkan warga yang tidak gemar membaca", s:1}], ex:"Pelayanan publik yang baik bersifat proaktif memperbaiki layanan yang sepi, bukan menyerah pada keadaan."},
{id:"TKP-1281", q:"Jadwal posyandu di desa Anda bentrok dengan hari pasar sehingga kehadiran ibu dan balita rendah. Tindakan Anda adalah ....", opts:[{t:"Berkordinasi dengan kader dan bidan desa untuk memindahkan jadwal posyandu ke hari non-pasar serta mensosialisasikannya lewat RT/RW", s:5},{t:"Tetap melaksanakan posyandu sesuai jadwal yang ada", s:4},{t:"Menggabungkan posyandu dengan kegiatan pasar", s:3},{t:"Mengurangi frekuensi posyandu karena sepi", s:2},{t:"Menghentikan posyandu dan menyalahkan warga", s:1}], ex:"Keberhasilan program pelayanan kesehatan desa bergantung pada penyesuaian jadwal dengan kehidupan warga."},
{id:"TKP-1282", q:"Warga mengeluhkan air bersih dari program penyediaan air minum desa yang sering mati. Mereka meminta penjelasan ke kantor desa. Anda akan ....", opts:[{t:"Menjelaskan penyebab gangguan secara terbuka, menyampaikan rencana perbaikan dan jadwalnya, serta membuka saluran pengaduan khusus", s:5},{t:"Menjelaskan bahwa sedang ada perbaikan tanpa kepastian jadwal", s:4},{t:"Meminta warga bersabar dan menunggu", s:3},{t:"Menyatakan itu bukan tanggung jawab kantor desa", s:2},{t:"Menuduh warga boros memakai air", s:1}], ex:"Keterbukaan informasi tentang gangguan layanan beserta rencana perbaikannya membangun kepercayaan warga."},
{id:"TKP-1283", q:"Kepala desa meminta Anda mendahulukan pelayanan untuk kerabatnya yang baru datang, melewati antrean warga lain. Sikap Anda adalah ....", opts:[{t:"Menolak dengan sopan dan tetap melayani sesuai urutan antrean sambil menjelaskan bahwa semua warga berhak dilayani sama", s:5},{t:"Melayani kerabat kepala desa itu dengan cepat agar tidak ditegur", s:4},{t:"Meminta kerabat tersebut antre tetapi memberinya nomor antrean terdepan", s:3},{t:"Menuruti perintah karena takut dimutasi", s:2},{t:"Memprioritaskan kerabat pejabat dalam semua layanan", s:1}], ex:"Prinsip kesetaraan dalam pelayanan publik tidak boleh dikalahkan oleh tekanan atasan; penolakan sopan adalah wujud integritas."},
{id:"TKP-1284", q:"Seorang warga membutuhkan surat pengantar pengukuran tanah ke BPN untuk mengurus sertipikat, tetapi batas tanahnya masih dipersoalkan tetangganya. Anda akan ....", opts:[{t:"Menerbitkan surat pengantar dengan catatan adanya sengketa batas, serta memfasilitasi mediasi awal antara kedua belah pihak", s:5},{t:"Menolak menerbitkan surat hingga sengketa selesai", s:4},{t:"Menerbitkan surat tanpa mencatat sengketa agar cepat", s:3},{t:"Menyuruh warga menyelesaikan sendiri dengan tetangganya", s:2},{t:"Menerbitkan surat palsu yang menyatakan tidak ada sengketa", s:1}], ex:"Pelayanan yang akuntabel mencatat fakta apa adanya sekaligus membantu penyelesaian masalah warga."},
{id:"TKP-1285", q:"Keluarga yang anggotanya baru meninggal membutuhkan surat keterangan kematian segera untuk pengurusan santunan, tetapi datang di luar jam layanan. Anda akan ....", opts:[{t:"Membantu menerbitkan suratnya segera karena sifatnya mendesak dan berkaitan dengan kedukaan", s:5},{t:"Memintanya datang kembali pada jam layanan", s:4},{t:"Mencatat keperluannya dan berjanji memproses pagi harinya", s:3},{t:"Menolak karena di luar jam kerja", s:2},{t:"Memintanya mengurus ke kelurahan tetangga", s:1}], ex:"Keadaan kedukaan dan kemendesakan adalah alasan sah untuk fleksibilitas pelayanan di luar jam kerja."},
{id:"TKP-1286", q:"Kader posyandu melaporkan adanya balita dengan tanda gizi buruk di dusun terpencil yang orang tuanya enggan ke puskesmas. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Berkordinasi dengan bidan desa dan kader untuk kunjungan rumah, membujuk orang tua dengan pendekatan persuasif, dan memfasilitasi rujukan", s:5},{t:"Meminta kader terus membujuk orang tuanya", s:4},{t:"Mencatat laporan dan menunggu orang tua datang sendiri", s:3},{t:"Mengabaikan karena itu tugas puskesmas", s:2},{t:"Menyalahkan orang tua yang tidak peduli anaknya", s:1}], ex:"Perangkat desa berperan aktif menjembatani layanan kesehatan hingga ke rumah warga yang enggan datang."},
{id:"TKP-1287", q:"Anda merangkap beberapa tugas pelayanan karena rekan Anda cuti, sehingga antrean warga menumpuk. Sikap terbaik adalah ....", opts:[{t:"Mengatur prioritas layanan berdasarkan urgensi, meminta bantuan perangkat lain, dan tetap melayani dengan ramah tanpa mengeluh", s:5},{t:"Melayani seadanya sesuai kemampuan sendiri", s:4},{t:"Meminta warga kembali setelah rekan Anda masuk kerja", s:3},{t:"Menutup sebagian loket layanan", s:2},{t:"Marah-marah kepada warga yang antre", s:1}], ex:"Keterbatasan personel bukan alasan menurunkan kualitas layanan; pengaturan prioritas dan kolaborasi adalah solusinya."},
{id:"TKP-1288", q:"Sejumlah warga protes karena dimintai pungutan biaya administrasi yang tidak jelas dasarnya saat mengurus KTP di desa. Anda akan ....", opts:[{t:"Menjelaskan rincian biaya resmi sesuai peraturan, menindaklanjuti dugaan pungutan liar, dan memasang daftar tarif layanan di papan pengumuman", s:5},{t:"Menjelaskan bahwa pengurusan KTP tidak dipungut biaya", s:4},{t:"Meminta warga melaporkan tertulis bila merasa dipungut liar", s:3},{t:"Mengabaikan protes karena bukan Anda yang memungut", s:2},{t:"Ikut memungut karena sudah menjadi kebiasaan", s:1}], ex:"Transparansi tarif layanan dan penindakan pungli melindungi warga sekaligus menjaga kepercayaan pada pemerintah desa."},
{id:"TKP-1289", q:"Jam layanan kantor desa (08.00-14.00) sering dikeluhkan warga yang bekerja sebagai petani dan buruh tani karena tidak bisa datang. Solusi terbaik yang Anda usulkan adalah ....", opts:[{t:"Mengusulkan penambahan jam layanan sore pada hari tertentu dan layanan keliling ke dusun pada musim tanam/panen", s:5},{t:"Mempertahankan jam layanan yang ada sesuai aturan", s:4},{t:"Meminta warga mengutus keluarganya yang tidak bekerja", s:3},{t:"Mengabaikan keluhan karena aturan jam kerja sudah baku", s:2},{t:"Menyatakan warga harus menyesuaikan diri dengan jam kantor", s:1}], ex:"Jam pelayanan publik idealnya menyesuaikan dengan pola kerja mayoritas warga yang dilayani."},
{id:"TKP-1290", q:"Seorang warga pendatang yang baru pindah ke desa Anda ingin mengurus surat keterangan pindah dan KTP baru, tetapi ia belum dikenal ketua RT setempat. Anda akan ....", opts:[{t:"Membantunya melengkapi pengantar RT/RW, memverifikasi dokumen kepindahannya, dan memproses sesuai prosedur tanpa mempersulit", s:5},{t:"Memintanya mengurus pengantar RT/RW sendiri terlebih dahulu", s:4},{t:"Menunda pelayanannya hingga ia dikenal warga", s:3},{t:"Menolak karena bukan warga asli desa", s:2},{t:"Memintanya kembali ke daerah asalnya saja", s:1}], ex:"Setiap warga negara berhak atas layanan administrasi kependudukan di domisilinya; status pendatang bukan alasan diskriminasi."},
{id:"TKP-1291", q:"Kotak saran di kantor desa penuh dengan keluhan tentang lambatnya pelayanan, tetapi tidak pernah ditindaklanjuti. Sebagai perangkat desa yang baru ditugaskan, Anda akan ....", opts:[{t:"Membaca seluruh saran, mengelompokkannya, membahas tindak lanjutnya dengan perangkat desa, dan mengumumkan hasilnya di papan pengumuman", s:5},{t:"Membaca saran-saran itu dan memperbaiki yang bisa diperbaiki sendiri", s:4},{t:"Mengosongkan kotak saran agar terlihat rapi", s:3},{t:"Membiarkan kotak saran apa adanya", s:2},{t:"Membuang isi kotak saran karena dianggap mengganggu", s:1}], ex:"Kotak saran hanya bermakna bila ditindaklanjuti dan hasilnya dikomunikasikan kembali kepada warga."},
{id:"TKP-1292", q:"Seorang warga tunanetra ingin mengetahui isi surat pemberitahuan pajak bumi dan bangunan yang diterimanya. Tindakan Anda adalah ....", opts:[{t:"Membacakan isi suratnya dengan jelas di tempat yang tenang, menjelaskan kewajibannya, dan menawarkan bantuan pengurusan", s:5},{t:"Membacakan isi suratnya secara singkat di loket", s:4},{t:"Memintanya meminta bantuan keluarganya membaca surat", s:3},{t:"Memberikan suratnya tanpa penjelasan", s:2},{t:"Menyuruhnya datang dengan pendamping lain kali", s:1}], ex:"Warga dengan keterbatasan penglihatan berhak mendapat penjelasan lisan yang jelas atas dokumen yang diterimanya."},
{id:"TKP-1293", q:"Lampu penerangan jalan desa di beberapa titik mati berbulan-bulan dan warga khawatir soal keamanan malam hari. Mereka melapor ke kantor desa. Anda akan ....", opts:[{t:"Mendata titik-titik yang mati, mengusulkan perbaikan pada anggaran pemeliharaan, dan mengupayakan perbaikan darurat untuk titik rawan", s:5},{t:"Mencatat laporan dan menyampaikan ke kepala desa", s:4},{t:"Meminta warga bersabar menunggu anggaran tahun depan", s:3},{t:"Mengabaikan karena dianggap bukan urusan mendesak", s:2},{t:"Menyalahkan warga yang merusak lampu", s:1}], ex:"Laporan warga soal fasilitas umum harus didata dan ditindaklanjuti dengan rencana perbaikan yang jelas."},
{id:"TKP-1294", q:"Sampah menumpuk di beberapa titik desa dan menimbulkan bau. Warga meminta pemerintah desa bertindak. Respons terbaik adalah ....", opts:[{t:"Berkordinasi dengan pengelola kebersihan, mengatur jadwal pengangkutan rutin, dan menggerakkan kerja bakti serta sosialisasi pemilahan sampah", s:5},{t:"Meminta petugas kebersihan menambah frekuensi pengangkutan", s:4},{t:"Mengimbau warga tidak membuang sampah sembarangan", s:3},{t:"Membiarkan karena keterbatasan armada", s:2},{t:"Menuduh warga yang membuang sampah sembarangan", s:1}], ex:"Masalah kebersihan diselesaikan dengan kombinasi perbaikan layanan, kerja bakti, dan edukasi warga."},
{id:"TKP-1295", q:"Seorang warga membutuhkan surat keterangan belum pernah menikah untuk syarat melamar TNI, tetapi data di arsip desa berbeda dengan pengakuannya. Anda akan ....", opts:[{t:"Menelusuri arsip dan memverifikasi ke RT/RW serta tetangga sebelum menerbitkan surat sesuai fakta yang benar", s:5},{t:"Menerbitkan surat sesuai pengakuannya agar cepat", s:4},{t:"Menolak menerbitkan karena datanya meragukan", s:3},{t:"Menyuruhnya mengurus ke pengadilan saja", s:2},{t:"Menerbitkan surat palsu sesuai keinginannya", s:1}], ex:"Surat keterangan harus berdasarkan verifikasi fakta, bukan sekadar pengakuan pemohon."},
{id:"TKP-1296", q:"Seorang siswa berprestasi dari keluarga miskin membutuhkan legalisir ijazah dan surat keterangan untuk pengajuan beasiswa yang tenggatnya besok. Anda akan ....", opts:[{t:"Memprioritaskan pengurusannya hari itu juga mengingat tenggat beasiswanya", s:5},{t:"Melayaninya sesuai antrean normal", s:4},{t:"Memintanya datang besok pagi-pagi", s:3},{t:"Menolak karena tenggatnya terlalu mepet", s:2},{t:"Memintanya mencari bantuan ke pihak lain", s:1}], ex:"Kasus dengan tenggat waktu yang jelas layak diprioritaskan sebagai wujud keberpihakan pada warga."},
{id:"TKP-1297", q:"Seorang warga marah-marah di loket karena permohonannya ditolak akibat syarat yang tidak terpenuhi. Ia membentak Anda di depan warga lain. Sikap Anda adalah ....", opts:[{t:"Tetap tenang, menjelaskan alasan penolakan dengan bahasa yang baik, dan menawarkan solusi agar syaratnya bisa dipenuhi", s:5},{t:"Menjelaskan aturan dengan tegas agar ia memahami", s:4},{t:"Memintanya tenang dan kembali setelah emosinya reda", s:3},{t:"Membentak balik karena merasa dilecehkan", s:2},{t:"Mengusirnya dari kantor desa", s:1}], ex:"Profesionalisme pelayanan diuji saat menghadapi warga yang emosi; ketenangan dan solusi adalah respons terbaik."},
{id:"TKP-1298", q:"Kepala desa sedang cuti dan ada warga membutuhkan tanda tangan surat mendesak. Anda sebagai perangkat desa akan ....", opts:[{t:"Menghubungi kepala desa sesuai mekanisme pendelegasian, atau meminta pejabat yang ditunjuk menandatangani sesuai aturan", s:5},{t:"Meminta warga menunggu hingga kepala desa kembali", s:4},{t:"Menandatangani sendiri atas nama kepala desa", s:3},{t:"Menolak melayani karena kepala desa tidak ada", s:2},{t:"Memalsukan tanda tangan kepala desa", s:1}], ex:"Pelayanan tidak boleh berhenti karena pejabat cuti; mekanisme pendelegasian wewenang harus dijalankan sesuai aturan."},
{id:"TKP-1299", q:"Kebakaran menghanguskan rumah seorang warga beserta seluruh dokumen kependudukannya. Ia membutuhkan surat-surat pengganti segera untuk pengurusan bantuan. Anda akan ....", opts:[{t:"Membantu menerbitkan kembali seluruh dokumennya berdasarkan arsip desa secara prioritas dan gratis", s:5},{t:"Menerbitkan dokumen pengganti sesuai prosedur normal", s:4},{t:"Memintanya mengurus satu per satu sesuai antrean", s:3},{t:"Memintanya membayar biaya penggantian dokumen", s:2},{t:"Menolak membantu karena dokumennya sudah hangus", s:1}], ex:"Korban bencana berhak mendapat prioritas dan kemudahan dalam pengurusan dokumen pengganti."},
{id:"TKP-1300", q:"Pendataan DTKS (Data Terpadu Kesejahteraan Sosial) menemukan banyak warga miskin yang belum terdata sehingga tidak mendapat bantuan. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Menggelar pendataan ulang bersama RT/RW secara menyeluruh, memverifikasi, dan mengusulkan perbaikan data ke dinas sosial", s:5},{t:"Mendata warga yang melapor saja", s:4},{t:"Menunggu jadwal pendataan dari kabupaten", s:3},{t:"Membiarkan karena data sudah ditetapkan", s:2},{t:"Memanipulasi data untuk memasukkan kerabat", s:1}], ex:"Ketidaktepatan data bantuan harus diperbaiki lewat pendataan ulang yang partisipatif, bukan dibiarkan."},
{id:"TKP-1301", q:"Warga mengeluhkan maraknya pencurian di malam hari dan meminta poskamling diaktifkan kembali. Anda akan ....", opts:[{t:"Berkordinasi dengan Babinsa, Bhabinkamtibmas, dan ketua RT untuk mengaktifkan kembali ronda malam secara bergiliran", s:5},{t:"Mengimbau warga meningkatkan kewaspadaan masing-masing", s:4},{t:"Meminta warga melapor bila terjadi pencurian", s:3},{t:"Mengabaikan karena keamanan bukan tugas desa", s:2},{t:"Menyalahkan warga yang tidak mau ronda", s:1}], ex:"Keamanan lingkungan adalah tanggung jawab bersama yang perlu difasilitasi pemerintah desa lewat koordinasi semua pihak."},
{id:"TKP-1302", q:"Seorang warga akan mengadakan hajatan pernikahan dan membutuhkan surat izin keramaian. Ia datang dua hari sebelum acara. Anda akan ....", opts:[{t:"Memproses surat izinnya segera mengingat waktunya mepet, dengan catatan ia melengkapi persyaratan yang kurang", s:5},{t:"Memproses sesuai antrean normal", s:4},{t:"Memintanya mengajukan jauh-jauh hari lain kali", s:3},{t:"Menolak karena pengajuannya terlalu mendadak", s:2},{t:"Menerbitkan izin tanpa syarat apa pun", s:1}], ex:"Pengajuan mepet tetap dilayani dengan mengingatkan ketertiban pengajuan, bukan ditolak."},
{id:"TKP-1303", q:"Seorang warga yang sebenarnya mampu meminta Anda menerbitkan surat keterangan tidak mampu agar anaknya mendapat bantuan. Ia menawarkan imbalan. Anda akan ....", opts:[{t:"Menolak dengan tegas dan sopan, menjelaskan bahwa surat harus sesuai kondisi sebenarnya hasil verifikasi", s:5},{t:"Menolak imbalannya tetapi tetap mempertimbangkan permohonannya", s:4},{t:"Menunda keputusan dan meminta pertimbangan atasan", s:3},{t:"Menerbitkan suratnya karena kasihan", s:2},{t:"Menerbitkan suratnya dan menerima imbalan", s:1}], ex:"Integritas berarti menolak menerbitkan keterangan yang tidak sesuai fakta, apa pun imbalannya."},
{id:"TKP-1304", q:"Seorang mantan pekerja migran yang baru pulang ke desa ingin mengurus dokumen kependudukan yang kedaluwarsa dan menanyakan program pemberdayaan purna TKI. Anda akan ....", opts:[{t:"Membantu pengurusan dokumennya dan menginformasikan program pelatihan serta akses permodalan bagi purna pekerja migran", s:5},{t:"Membantu pengurusan dokumennya saja", s:4},{t:"Mengarahkannya bertanya ke dinas tenaga kerja", s:3},{t:"Melayaninya seadanya tanpa informasi tambahan", s:2},{t:"Mengabaikannya karena bukan prioritas", s:1}], ex:"Pelayanan yang baik tidak berhenti pada dokumen, tetapi menyambungkan warga dengan program pemberdayaan yang relevan."},
{id:"TKP-1305", q:"Ditemukan anak putus sekolah di desa Anda karena orang tuanya tidak mampu membiayai. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Mendata anak tersebut, menginformasikan program beasiswa dan sekolah gratis, serta membantu pengurusan persyaratannya", s:5},{t:"Menyarankan orang tuanya menyekolahkan kembali anaknya", s:4},{t:"Mencatat kasusnya untuk laporan", s:3},{t:"Membiarkan karena itu urusan keluarga", s:2},{t:"Menyalahkan orang tua yang tidak memprioritaskan pendidikan", s:1}], ex:"Perangkat desa berperan aktif memastikan tidak ada anak yang kehilangan hak pendidikan karena kemiskinan."},
{id:"TKP-1306", q:"Seorang lansia sebatang kara di desa Anda hidup dalam kondisi memprihatinkan dan belum tersentuh bantuan apa pun. Tindakan Anda adalah ....", opts:[{t:"Mengusulkan namanya masuk dalam data penerima bantuan, berkordinasi dengan dinas sosial, dan menggerakkan kepedulian RT/RW setempat", s:5},{t:"Melaporkannya ke kepala desa untuk ditindaklanjuti", s:4},{t:"Meminta tetangganya membantu semampunya", s:3},{t:"Menunggu ada program bantuan baru", s:2},{t:"Mengabaikan karena bukan tanggung jawab Anda", s:1}], ex:"Kelompok paling rentan harus proaktif dicari dan dibantu, bukan menunggu mereka melapor."},
{id:"TKP-1307", q:"Dua ketua RT berselisih soal batas wilayah sehingga warga di perbatasan bingung harus mengurus surat ke RT mana. Anda akan ....", opts:[{t:"Memfasilitasi pertemuan kedua ketua RT dengan membawa peta dan arsip wilayah untuk menetapkan batas secara musyawarah", s:5},{t:"Meminta keduanya menyelesaikan sendiri", s:4},{t:"Menetapkan batas sepihak berdasarkan arsip", s:3},{t:"Membiarkan warga memilih RT sendiri", s:2},{t:"Memihak salah satu ketua RT yang lebih dekat dengan Anda", s:1}], ex:"Perselisihan batas wilayah diselesaikan lewat fasilitasi musyawarah berbasis data, bukan pembiaran atau pemihakan."},
{id:"TKP-1308", q:"Seorang warga meminta surat keterangan ahli waris berdasarkan hukum adat setempat untuk sebidang tanah. Anda akan ....", opts:[{t:"Menerbitkan surat sesuai hasil musyawarah keluarga dan keterangan tokoh adat, dengan mencatat dasarnya secara jelas", s:5},{t:"Menerbitkan surat sesuai permintaannya saja", s:4},{t:"Menolak karena hanya mengakui hukum formal", s:3},{t:"Menyuruhnya ke pengadilan tanpa membantu", s:2},{t:"Menerbitkan surat tanpa verifikasi apa pun", s:1}], ex:"Kearifan lokal dihormati dengan tetap mendasarkan surat pada verifikasi dan pencatatan yang jelas."},
{id:"TKP-1309", q:"Layanan kesehatan keliling puskesmas ke desa Anda sepi karena warga tidak tahu jadwalnya. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Berkordinasi dengan puskesmas untuk jadwal tetap, lalu mensosialisasikannya lewat pengeras suara masjid, RT/RW, dan grup warga", s:5},{t:"Meminta puskesmas mengumumkan sendiri jadwalnya", s:4},{t:"Menempel pengumuman di papan informasi desa", s:3},{t:"Membiarkan karena itu program puskesmas", s:2},{t:"Melaporkan puskesmas tidak serius ke dinas kesehatan", s:1}], ex:"Perangkat desa menjadi penghubung aktif agar program layanan kesehatan benar-benar sampai ke warga."},
{id:"TKP-1310", q:"Anda diminta membuat survei kepuasan warga terhadap pelayanan kantor desa. Cara terbaik melakukannya adalah ....", opts:[{t:"Menyebarkan kuesioner sederhana ke warga yang dilayani, merekap hasilnya secara terbuka, dan menjadikannya bahan perbaikan layanan", s:5},{t:"Meminta penilaian lisan dari beberapa warga", s:4},{t:"Membuat laporan kepuasan berdasarkan perkiraan sendiri", s:3},{t:"Tidak melakukan survei karena merepotkan", s:2},{t:"Memalsukan hasil survei agar terlihat bagus", s:1}], ex:"Survei kepuasan harus berbasis data nyata dari warga dan hasilnya dipakai untuk perbaikan, bukan formalitas."},
{id:"TKP-1311", q:"Kontraktor proyek jalan desa menawarkan Anda fee agar nilai proyek di-markup dalam laporan pertanggungjawaban dana desa. Sikap Anda adalah ....", opts:[{t:"Menolak dengan tegas, melaporkan tawaran tersebut ke kepala desa dan inspektorat, serta memastikan laporan sesuai realisasi", s:5},{t:"Menolak tawaran tetapi tidak melaporkan ke siapa pun", s:4},{t:"Mempertimbangkan tawaran sambil menunda keputusan", s:3},{t:"Menerima fee karena merasa gaji perangkat desa kecil", s:2},{t:"Menerima fee dan membantu memalsukan laporan", s:1}], ex:"Integritas menuntut penolakan tegas terhadap suap sekaligus pelaporan agar praktiknya tidak berulang."},
{id:"TKP-1312", q:"Kepala desa memerintahkan Anda membuat laporan kegiatan fiktif untuk menyerap sisa dana desa akhir tahun. Anda akan ....", opts:[{t:"Menolak dengan sopan, menjelaskan risikonya, dan mengusulkan realokasi resmi sesuai mekanisme perubahan APBDes", s:5},{t:"Menolak perintah tetapi tidak memberi alternatif solusi", s:4},{t:"Menunda-nunda pembuatan laporan yang diminta", s:3},{t:"Membuat laporan fiktif karena perintah atasan", s:2},{t:"Membuat laporan fiktif dan meminta bagian", s:1}], ex:"Perintah atasan yang melanggar aturan wajib ditolak; loyalitas sejati adalah menjaga atasan dari pelanggaran."},
{id:"TKP-1313", q:"Daftar penerima BLT Dana Desa yang sudah ditetapkan lewat musdes diminta diubah oleh kepala desa untuk memasukkan kerabatnya yang tidak memenuhi syarat. Anda akan ....", opts:[{t:"Menolak mengubah data, berpegang pada hasil musdes dan kriteria resmi, serta mendokumentasikan penolakan Anda", s:5},{t:"Menolak tetapi tidak berani mendokumentasikan", s:4},{t:"Mengubah sebagian kecil agar tidak kentara", s:3},{t:"Mengubah data sesuai perintah", s:2},{t:"Mengubah data dan menghapus jejak perubahan", s:1}], ex:"Data penerima bantuan yang ditetapkan musyawarah tidak boleh diubah sepihak demi kepentingan kerabat pejabat."},
{id:"TKP-1314", q:"Seorang warga memberikan parsel mahal kepada Anda setelah suratnya selesai diurus, sebagai ucapan terima kasih. Tindakan terbaik adalah ....", opts:[{t:"Menolak dengan sopan dan menjelaskan bahwa melayani warga adalah tugas tanpa perlu imbalan", s:5},{t:"Menerima parsel karena sudah selesai dan tidak memengaruhi layanan", s:4},{t:"Menerima parsel lalu membagikannya ke rekan kerja", s:3},{t:"Menerima parsel dan mengharapkan hal serupa dari warga lain", s:2},{t:"Meminta parsel lebih besar lain kali", s:1}], ex:"Gratifikasi dalam bentuk apa pun, meski setelah layanan selesai, tetap wajib ditolak untuk menjaga integritas."},
{id:"TKP-1315", q:"Menjelang pemilihan kepala desa, calon petahana meminta Anda sebagai perangkat desa mengarahkan warga memilihnya dengan iming-iming jabatan. Anda akan ....", opts:[{t:"Menolak tegas dan menjaga netralitas, serta melaporkan tekanan tersebut ke panitia pemilihan/bawaslu", s:5},{t:"Menolak tetapi diam saja", s:4},{t:"Bersikap netral pasif tanpa menolak ajakan", s:3},{t:"Diam-diam membantu calon petahana", s:2},{t:"Aktif berkampanye untuk petahana demi jabatan", s:1}], ex:"Netralitas perangkat desa dalam pilkades adalah kewajiban hukum; tekanan politik harus ditolak dan dilaporkan."},
{id:"TKP-1316", q:"Rekrutmen perangkat desa baru diduga diatur agar anak kepala desa yang lolos meski nilainya tidak terbaik. Anda anggota panitia seleksi. Sikap Anda adalah ....", opts:[{t:"Menegakkan hasil seleksi berdasarkan nilai objektif dan melaporkan intervensi ke pihak berwenang", s:5},{t:"Protes secara lisan tetapi tetap mengikuti hasil yang diatur", s:4},{t:"Diam karena takut dimusuhi kepala desa", s:3},{t:"Ikut meloloskan anak kepala desa", s:2},{t:"Aktif membantu memanipulasi nilai seleksi", s:1}], ex:"Rekrutmen aparatur harus berbasis merit; intervensi kekuasaan wajib dilawan demi keadilan."},
{id:"TKP-1317", q:"Stempel resmi desa dipinjam rekan Anda untuk keperluan yang tidak jelas di luar jam kerja. Anda yang memegang stempel akan ....", opts:[{t:"Menolak meminjamkan dan menjelaskan bahwa stempel hanya dipakai untuk keperluan dinas yang sah", s:5},{t:"Meminjamkan dengan catatan dikembalikan cepat", s:4},{t:"Meminjamkan karena percaya pada rekan", s:3},{t:"Membiarkan rekan mengambil sendiri", s:2},{t:"Ikut memakai stempel untuk kepentingan pribadi", s:1}], ex:"Atribut resmi negara seperti stempel tidak boleh dipinjamkan untuk keperluan tidak jelas."},
{id:"TKP-1318", q:"Kendaraan operasional desa sering dipakai kepala desa untuk keperluan keluarga di luar dinas. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Menyampaikan keberatan secara sopan melalui mekanisme yang benar dan mengusulkan aturan pemakaian kendaraan dinas", s:5},{t:"Diam saja karena itu wewenang kepala desa", s:4},{t:"Ikut memakai kendaraan dinas untuk keperluan pribadi", s:3},{t:"Menyebarkan gosip tentang hal itu ke warga", s:2},{t:"Mengambil alih kendaraan untuk kepentingan sendiri", s:1}], ex:"Aset desa harus dipakai untuk kepentingan dinas; penyimpangan disampaikan lewat jalur resmi, bukan gosip."},
{id:"TKP-1319", q:"Anda menemukan kas kecil operasional desa dipakai bendahara untuk keperluan pribadi dengan janji dikembalikan. Anda akan ....", opts:[{t:"Menegur bendahara dan melaporkannya ke kepala desa agar segera dikembalikan dan tidak terulang", s:5},{t:"Menegur bendahara secara pribadi saja", s:4},{t:"Membiarkan karena akan dikembalikan juga", s:3},{t:"Ikut meminjam kas desa untuk keperluan pribadi", s:2},{t:"Menyebarkan kabar itu ke warga", s:1}], ex:"Penggunaan kas desa untuk pribadi adalah pelanggaran yang harus ditegur dan dilaporkan lewat jalur resmi."},
{id:"TKP-1320", q:"Proyek pembangunan drainase desa dikerjakan oleh CV milik adik kepala desa tanpa proses lelang yang benar. Anda mengetahuinya. Sikap Anda adalah ....", opts:[{t:"Melaporkan dugaan konflik kepentingan dan pelanggaran pengadaan ke inspektorat melalui mekanisme resmi", s:5},{t:"Menyampaikan keberatan lisan ke kepala desa", s:4},{t:"Diam karena bukan urusan Anda", s:3},{t:"Ikut menikmati keuntungan proyek", s:2},{t:"Membantu menutupi pelanggaran pengadaan", s:1}], ex:"Konflik kepentingan dalam pengadaan desa wajib dilaporkan; pembiaran sama dengan persetujuan."},
{id:"TKP-1321", q:"Anda diminta menandatangani berita acara serah terima pekerjaan proyek desa padahal pekerjaan belum selesai 100%. Anda akan ....", opts:[{t:"Menolak menandatangani hingga pekerjaan benar-benar selesai dan terverifikasi", s:5},{t:"Menandatangani dengan catatan pekerjaan kurang", s:4},{t:"Menandatangani karena didesak atasan", s:3},{t:"Menandatangani tanpa memeriksa", s:2},{t:"Menandatangani dan meminta imbalan", s:1}], ex:"Tanda tangan adalah pertanggungjawaban; menandatangani yang belum selesai berarti memalsukan fakta."},
{id:"TKP-1322", q:"Tim inspektorat menemukan kejanggalan penggunaan dana desa dan meminta keterangan Anda. Atasan meminta Anda menutup-nutupi. Anda akan ....", opts:[{t:"Memberikan keterangan yang jujur dan apa adanya kepada inspektorat", s:5},{t:"Memberikan keterangan seadanya tanpa berbohong", s:4},{t:"Menghindari pemeriksaan dengan berbagai alasan", s:3},{t:"Menutup-nutupi sesuai perintah atasan", s:2},{t:"Memberikan keterangan palsu untuk melindungi atasan", s:1}], ex:"Kejujuran kepada aparat pengawas adalah kewajiban; perintah menutup-nutupi tidak boleh ditaati."},
{id:"TKP-1323", q:"Seorang warga diminta membayar biaya di luar ketentuan saat mengurus KTP oleh oknum perangkat desa. Ia melapor kepada Anda. Tindakan Anda adalah ....", opts:[{t:"Menerima laporan, menindaklanjuti ke kepala desa, dan memastikan warga mendapat layanan tanpa pungutan liar", s:5},{t:"Menyarankan warga melapor tertulis ke kepala desa", s:4},{t:"Meminta warga bersabar dan melupakan kejadian itu", s:3},{t:"Mengabaikan laporan karena melibatkan rekan", s:2},{t:"Membela oknum tersebut dan menyalahkan warga", s:1}], ex:"Laporan pungli harus ditindaklanjuti, bukan diabaikan demi solidaritas sesama perangkat."},
{id:"TKP-1324", q:"Teman dekat Anda meminta dibuatkan surat keterangan domisili palsu untuk syarat tender proyek. Anda akan ....", opts:[{t:"Menolak dengan tegas dan menjelaskan bahwa pemalsuan dokumen adalah tindak pidana", s:5},{t:"Menolak tetapi tidak menjelaskan alasannya", s:4},{t:"Menunda dengan alasan sibuk", s:3},{t:"Membuatkan surat palsu demi persahabatan", s:2},{t:"Membuatkan surat palsu dan meminta imbalan", s:1}], ex:"Persahabatan tidak boleh mengalahkan hukum; pemalsuan dokumen resmi adalah tindak pidana."},
{id:"TKP-1325", q:"Anda sering datang terlambat ke kantor desa dengan alasan jarak rumah jauh, padahal warga sudah menunggu. Sikap yang seharusnya adalah ....", opts:[{t:"Memperbaiki disiplin dengan berangkat lebih awal dan meminta maaf kepada warga atas keterlambatan selama ini", s:5},{t:"Berusaha datang tepat waktu mulai besok", s:4},{t:"Tetap terlambat tetapi bekerja lebih cepat", s:3},{t:"Menyalahkan kondisi jalan yang rusak", s:2},{t:"Menganggap keterlambatan hal biasa di desa", s:1}], ex:"Disiplin waktu adalah bentuk penghormatan pada warga yang dilayani; alasan pribadi bukan pembenaran."},
{id:"TKP-1326", q:"Atasan memerintahkan Anda melakukan sesuatu yang jelas-jelas melanggar peraturan perundang-undangan. Prinsip yang benar adalah ....", opts:[{t:"Menolak perintah tersebut dan menjelaskan dasar aturannya, serta melaporkannya bila tekanan berlanjut", s:5},{t:"Menolak tetapi tidak berani menjelaskan", s:4},{t:"Melaksanakan sebagian perintah saja", s:3},{t:"Melaksanakan karena perintah atasan wajib ditaati", s:2},{t:"Melaksanakan dan menyembunyikan pelanggaran", s:1}], ex:"Ketaatan pada atasan berhenti pada perintah yang melanggar hukum; itulah makna loyalitas yang benar."},
{id:"TKP-1327", q:"Anda salah menginput data keuangan di Siskeudes sehingga laporan menjadi tidak sesuai. Kesalahan belum diketahui siapa pun. Anda akan ....", opts:[{t:"Segera memperbaiki kesalahan, mendokumentasikan koreksinya, dan melaporkannya ke atasan", s:5},{t:"Memperbaiki diam-diam tanpa melapor", s:4},{t:"Membiarkan karena jumlahnya kecil", s:3},{t:"Menyalahkan sistem aplikasi", s:2},{t:"Menutupi kesalahan dengan memanipulasi data lain", s:1}], ex:"Kesalahan administrasi diakui dan diperbaiki secara terbuka; menutupi justru memperbesar masalah."},
{id:"TKP-1328", q:"Rancangan APBDes yang belum ditetapkan diminta bocorkan oleh seorang warga yang mengaku kerabat kepala desa. Anda akan ....", opts:[{t:"Menolak dan menjelaskan bahwa dokumen akan dibuka ke publik setelah ditetapkan sesuai prosedur", s:5},{t:"Menolak tanpa penjelasan", s:4},{t:"Memberikan bocoran sebagian", s:3},{t:"Memberikan seluruh dokumen", s:2},{t:"Memberikan dokumen dan meminta imbalan", s:1}], ex:"Transparansi anggaran tetap mengikuti prosedur; dokumen yang belum sah tidak boleh dibocorkan."},
{id:"TKP-1329", q:"Fasilitas balai desa dipakai untuk kegiatan kampanye salah satu calon kepala desa atas izin kepala desa petahana. Anda akan ....", opts:[{t:"Menolak terlibat dan melaporkan penyalahgunaan fasilitas negara untuk kampanye ke panitia pengawas", s:5},{t:"Tidak ikut terlibat tetapi diam saja", s:4},{t:"Ikut membantu persiapan acaranya", s:3},{t:"Mendukung karena diperintah atasan", s:2},{t:"Aktif berkampanye menggunakan fasilitas desa", s:1}], ex:"Fasilitas negara tidak boleh dipakai untuk kampanye; penyalahgunaannya wajib dilaporkan."},
{id:"TKP-1330", q:"Seorang pengusaha menawarkan Anda uang agar izin usahanya di desa dipercepat tanpa melengkapi AMDAL sederhana yang disyaratkan. Anda akan ....", opts:[{t:"Menolak dan tetap memproses izin sesuai prosedur lengkap demi kelestarian lingkungan desa", s:5},{t:"Menolak uangnya tetapi mempercepat prosesnya", s:4},{t:"Mempertimbangkan tawaran karena nilainya besar", s:3},{t:"Menerima uang dan mempercepat izin", s:2},{t:"Menerima uang dan menerbitkan izin tanpa syarat", s:1}], ex:"Perizinan yang berkaitan dengan lingkungan tidak boleh dikompromikan dengan suap."},
{id:"TKP-1331", q:"Laporan pertanggungjawaban studi banding perangkat desa ke luar daerah diduga fiktif karena tidak ada dokumentasi kegiatan. Anda ikut dalam rombongan. Sikap Anda adalah ....", opts:[{t:"Menyampaikan keberatan dan meminta laporan dibuat sesuai fakta sebenarnya", s:5},{t:"Diam saja karena bukan Anda yang membuat laporan", s:4},{t:"Menandatangani laporan yang ada", s:3},{t:"Ikut menikmati perjalanan tanpa peduli laporan", s:2},{t:"Membantu memalsukan dokumentasi kegiatan", s:1}], ex:"Setiap rupiah anggaran harus dipertanggungjawabkan sesuai fakta; laporan fiktif adalah pelanggaran."},
{id:"TKP-1332", q:"Dana operasional kantor desa penggunaannya tidak jelas dan tidak pernah dilaporkan. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Mengusulkan pencatatan dan pelaporan rutin dana operasional agar transparan dan bisa dipertanggungjawabkan", s:5},{t:"Menanyakan penggunaannya ke bendahara", s:4},{t:"Membiarkan karena bukan tugas Anda", s:3},{t:"Ikut menggunakan tanpa pencatatan", s:2},{t:"Menyebarkan isu penyelewengan ke warga", s:1}], ex:"Setiap penggunaan dana publik wajib tercatat dan dilaporkan; mengusulkan sistemnya adalah langkah konstruktif."},
{id:"TKP-1333", q:"Bantuan sembako dari program desa selalu diprioritaskan untuk keluarga perangkat desa, bukan warga yang paling membutuhkan. Anda akan ....", opts:[{t:"Mengusulkan pendataan ulang berbasis kriteria resmi dan penyaluran terbuka yang bisa diawasi warga", s:5},{t:"Protes secara pribadi ke kepala desa", s:4},{t:"Diam karena ikut mendapat bagian", s:3},{t:"Mendukung karena loyal pada atasan", s:2},{t:"Ikut mengatur pembagian untuk keluarga sendiri", s:1}], ex:"Bantuan sosial harus berbasis kebutuhan, bukan kedekatan dengan aparat; sistem terbuka mencegah nepotisme."},
{id:"TKP-1334", q:"Anda diminta menjadi auditor internal penggunaan dana BUMDes, tetapi pengurus BUMDes adalah saudara Anda. Sikap profesional adalah ....", opts:[{t:"Menyatakan konflik kepentingan dan meminta orang lain yang independen melakukan audit", s:5},{t:"Tetap melakukan audit dengan seobjektif mungkin", s:4},{t:"Melakukan audit seadanya", s:3},{t:"Meloloskan laporan tanpa pemeriksaan mendalam", s:2},{t:"Membantu menutupi kerugian BUMDes", s:1}], ex:"Konflik kepentingan harus dihindari dengan mundur dari tugas yang melibatkan kerabat, bukan diatasi dengan niat baik semata."},
{id:"TKP-1335", q:"Seorang warga mengancam akan memviralkan Anda bila permohonannya yang tidak sesuai syarat tidak dikabulkan. Anda akan ....", opts:[{t:"Tetap berpegang pada aturan, menjelaskan dengan tenang, dan tidak gentar pada ancaman", s:5},{t:"Tetap menolak tetapi dengan nada marah", s:4},{t:"Mengabulkan sebagian permohonannya agar tidak viral", s:3},{t:"Mengabulkan permohonannya karena takut viral", s:2},{t:"Balik mengancam warga tersebut", s:1}], ex:"Ancaman viral tidak boleh membengkokkan aturan; ketegasan yang sopan menunjukkan integritas."},
{id:"TKP-1336", q:"Rekan kerja Anda ketahuan memalsukan tanda tangan warga pada dokumen bantuan. Ia meminta Anda merahasiakannya. Anda akan ....", opts:[{t:"Menolak merahasiakan dan melaporkannya karena pemalsuan tanda tangan adalah pelanggaran serius", s:5},{t:"Menegurnya agar tidak mengulangi tetapi tidak melapor", s:4},{t:"Diam dan tidak ikut campur", s:3},{t:"Merahasiakan demi solidaritas rekan", s:2},{t:"Ikut membantu memalsukan dokumen lain", s:1}], ex:"Solidaritas tidak berlaku untuk pelanggaran hukum; pemalsuan wajib dilaporkan."},
{id:"TKP-1337", q:"Anda ditawari pekerjaan sampingan yang jamnya berbenturan dengan jam layanan kantor desa. Tawaran gajinya menggiurkan. Keputusan Anda adalah ....", opts:[{t:"Menolak pekerjaan yang mengganggu tugas utama sebagai pelayan masyarakat", s:5},{t:"Mengambil tetapi berusaha tidak mengganggu jam kerja", s:4},{t:"Mengambil dan sering izin dari kantor", s:3},{t:"Mengambil dan menitipkan tugas ke rekan", s:2},{t:"Mengambil dan mengabaikan tugas kantor", s:1}], ex:"Tugas pelayanan publik adalah prioritas; pekerjaan sampingan tidak boleh mengorbankan kewajiban utama."},
{id:"TKP-1338", q:"Pengadaan barang untuk kantor desa dilakukan tanpa membandingkan harga dari beberapa penyedia. Anda mengetahuinya. Anda akan ....", opts:[{t:"Mengingatkan pentingnya prinsip efisiensi dan kompetisi harga sesuai aturan pengadaan", s:5},{t:"Menanyakan alasannya ke panitia pengadaan", s:4},{t:"Membiarkan karena sudah biasa begitu", s:3},{t:"Ikut menunjuk penyedia langganan", s:2},{t:"Meminta komisi dari penyedia yang ditunjuk", s:1}], ex:"Prinsip pengadaan yang efisien dan kompetitif wajib dijunjung meski skalanya desa."},
{id:"TKP-1339", q:"Data kependudukan warga desa diminta oleh seorang marketing asuransi dengan imbalan. Anda yang mengelola data akan ....", opts:[{t:"Menolak tegas karena data pribadi warga dilindungi undang-undang", s:5},{t:"Menolak tetapi tidak menjelaskan alasannya", s:4},{t:"Memberikan data yang tidak lengkap saja", s:3},{t:"Memberikan data karena imbalannya besar", s:2},{t:"Menjual data warga secara rutin", s:1}], ex:"Data pribadi warga adalah amanah yang dilindungi hukum; memperjualbelikannya adalah pelanggaran berat."},
{id:"TKP-1340", q:"Kongkalikong tender proyek BUMDes tercium warga dan mereka meminta penjelasan kepada Anda sebagai perangkat desa. Anda akan ....", opts:[{t:"Mendorong dilakukannya evaluasi terbuka dan audit independen atas tender tersebut", s:5},{t:"Menjelaskan bahwa tender sudah sesuai prosedur", s:4},{t:"Meminta warga tidak ikut campur urusan BUMDes", s:3},{t:"Menutupi dugaan kongkalikong", s:2},{t:"Ikut menikmati hasil kongkalikong", s:1}], ex:"Dugaan penyimpangan di badan usaha milik desa harus dijawab dengan audit independen, bukan penutupan."},
{id:"TKP-1341", q:"Seorang pelapor dugaan pungli di kantor desa diintimidasi oleh oknum perangkat. Anda menyaksikannya. Sikap Anda adalah ....", opts:[{t:"Melindungi pelapor dan melaporkan intimidasi tersebut ke kepala desa atau pihak berwenang", s:5},{t:"Menenangkan pelapor secara pribadi", s:4},{t:"Diam karena takut ikut diintimidasi", s:3},{t:"Ikut mengintimidasi agar pelapor mencabut laporan", s:2},{t:"Menyebarkan identitas pelapor ke warga", s:1}], ex:"Pelapor pelanggaran wajib dilindungi; intimidasi terhadapnya adalah pelanggaran yang harus dilaporkan."},
{id:"TKP-1342", q:"Anda menerima bingkisan dari rekanan proyek desa menjelang hari raya. Nilai bingkisan cukup besar. Tindakan yang benar adalah ....", opts:[{t:"Menolak atau melaporkannya sebagai gratifikasi sesuai ketentuan", s:5},{t:"Menerima karena dianggap budaya hari raya", s:4},{t:"Menerima dan membagikan ke rekan lain", s:3},{t:"Menerima dengan senang hati", s:2},{t:"Meminta bingkisan serupa setiap hari raya", s:1}], ex:"Bingkisan dari rekanan adalah gratifikasi yang wajib ditolak atau dilaporkan, apa pun momennya."},
{id:"TKP-1343", q:"Kepala dusun memutasi ketua RT yang kritis terhadapnya tanpa alasan jelas. Warga meminta pendapat Anda. Anda akan ....", opts:[{t:"Menjelaskan mekanisme yang benar dan mendorong penyelesaian lewat musyawarah, bukan pemecatan sepihak", s:5},{t:"Menyarankan warga menerima keputusan", s:4},{t:"Tidak berpendapat karena bukan wewenang Anda", s:3},{t:"Mendukung pemutasi demi menjaga hubungan baik", s:2},{t:"Ikut menekan ketua RT yang kritis", s:1}], ex:"Wewenang tidak boleh dipakai membungkam kritik; penyelesaian harus lewat mekanisme yang adil."},
{id:"TKP-1344", q:"Anda mengetahui rekan perangkat desa menitip absen setiap pagi padahal sering datang siang. Anda akan ....", opts:[{t:"Menegur rekan tersebut dan melaporkan bila berlanjut, karena merusak disiplin dan kepercayaan warga", s:5},{t:"Menegurnya secara pribadi saja", s:4},{t:"Membiarkan karena sudah biasa", s:3},{t:"Ikut menitip absen", s:2},{t:"Memeras rekan tersebut agar tidak melapor", s:1}], ex:"Titip absen adalah ketidakjujuran yang merusak integritas institusi; wajib ditegur dan dilaporkan bila berlanjut."},
{id:"TKP-1345", q:"Unggahan media sosial Anda sebagai perangkat desa sebaiknya ....", opts:[{t:"Menjaga etika, tidak menyebar hoaks, dan tidak menjelekkan institusi maupun warga", s:5},{t:"Bebas mengunggah apa saja karena akun pribadi", s:4},{t:"Sesekali mengeluhkan pekerjaan agar viral", s:3},{t:"Menyebar informasi internal desa yang belum resmi", s:2},{t:"Menghina warga yang mengkritik di media sosial", s:1}], ex:"Perangkat desa tetap membawa nama institusi di ruang digital; etika bermedia sosial wajib dijaga."},
{id:"TKP-1346", q:"Loyalitas kepada atasan menurut nilai ASN BerAKHLAK berarti ....", opts:[{t:"Mendukung atasan dengan cara yang benar, termasuk mengingatkan bila atasan keliru", s:5},{t:"Selalu menuruti semua perintah atasan", s:4},{t:"Tidak pernah mengkritik atasan di depan umum", s:3},{t:"Menutupi kesalahan atasan dari siapa pun", s:2},{t:"Membela atasan meski jelas melanggar hukum", s:1}], ex:"Loyalitas sejati adalah menjaga atasan tetap pada koridor yang benar, bukan kepatuhan buta."},
{id:"TKP-1347", q:"Rekan Anda berbuat kesalahan dalam pelayanan yang merugikan warga, lalu meminta Anda menutupinya. Anda akan ....", opts:[{t:"Menolak menutupi, mendorong rekan mengakui dan memperbaiki kesalahannya kepada warga", s:5},{t:"Menutupinya kali ini dengan syarat tidak diulangi", s:4},{t:"Diam dan tidak terlibat", s:3},{t:"Membantu menutupi kesalahan rekan", s:2},{t:"Menyalahkan warga agar rekan aman", s:1}], ex:"Kesalahan harus diakui dan diperbaiki, bukan ditutupi; itulah akuntabilitas."},
{id:"TKP-1348", q:"Anggaran kegiatan karang taruna tidak bisa dipertanggungjawabkan pengurusnya. Sebagai pembina perangkat desa, Anda akan ....", opts:[{t:"Meminta pertanggungjawaban tertulis, membantu menyusun laporannya, dan menjadikannya pembelajaran tertib administrasi", s:5},{t:"Meminta pertanggungjawaban lisan saja", s:4},{t:"Membiarkan karena nominalnya kecil", s:3},{t:"Menutupi kekurangan dengan dana lain", s:2},{t:"Ikut menggunakan sisa anggaran tanpa laporan", s:1}], ex:"Pembinaan berarti menuntut pertanggungjawaban sekaligus mengajari tertib administrasi, bukan memaklumi."},
{id:"TKP-1349", q:"Warga menawarkan Anda menjadi makelar proyek desa dengan imbalan besar. Tawaran itu ....", opts:[{t:"Ditolak tegas dan dilaporkan sebagai upaya suap", s:5},{t:"Ditolak secara halus", s:4},{t:"Dipertimbangkan sambil menunda", s:3},{t:"Diterima diam-diam", s:2},{t:"Diterima dan dijalankan", s:1}], ex:"Menjadi makelar proyek adalah bentuk korupsi; wajib ditolak dan dilaporkan."},
{id:"TKP-1350", q:"Prinsip akuntabel bagi perangkat desa dalam mengelola dana desa berarti ....", opts:[{t:"Setiap penggunaan dana dapat dijelaskan, dibuktikan dokumen, dan dipertanggungjawabkan kepada publik", s:5},{t:"Dana digunakan sesuai perintah kepala desa", s:4},{t:"Laporan dibuat asal ada", s:3},{t:"Penggunaan dana cukup diketahui perangkat desa", s:2},{t:"Dana desa boleh dipakai dulu, laporan belakangan", s:1}], ex:"Akuntabilitas adalah kemampuan mempertanggungjawabkan setiap rupiah dana publik secara terbuka dan terdokumentasi."},
{id:"TKP-1351", q:"Kaur keuangan dan kaur perencanaan di kantor desa Anda saling lempar tanggung jawab soal keterlambatan laporan APBDes. Sebagai rekan kerja, Anda akan ....", opts:[{t:"Memfasilitasi keduanya duduk bersama membagi tugas yang jelas dengan tenggat, lalu memantau penyelesaiannya", s:5},{t:"Menegur keduanya agar tidak bertengkar", s:4},{t:"Membiarkan mereka menyelesaikan sendiri", s:3},{t:"Memihak salah satu yang lebih dekat dengan Anda", s:2},{t:"Melaporkan keduanya ke kepala desa agar dihukum", s:1}], ex:"Kolaborasi berarti aktif menjembatani rekan yang berselisih dengan pembagian tugas yang jelas."},
{id:"TKP-1352", q:"BPD menolak rancangan APBDes yang diajukan pemerintah desa karena dianggap tidak aspiratif. Sebagai perangkat desa, sikap Anda adalah ....", opts:[{t:"Membuka dialog, menampung masukan BPD, dan merevisi rancangan bersama hingga disepakati", s:5},{t:"Meminta kepala desa melobi ketua BPD", s:4},{t:"Mengabaikan penolakan BPD", s:3},{t:"Menekan BPD agar menyetujui", s:2},{t:"Memalsukan persetujuan BPD", s:1}], ex:"BPD adalah mitra sejajar; perbedaan pendapat diselesaikan lewat dialog dan revisi bersama."},
{id:"TKP-1353", q:"Ketua RT tidak kompak dalam pendataan warga miskin sehingga data dari tiap RT timpang. Anda sebagai koordinator pendataan akan ....", opts:[{t:"Mengumpulkan para ketua RT, menyamakan persepsi kriteria, dan mendampingi pendataan hingga selesai", s:5},{t:"Meminta ketua RT yang tidak kompak diganti", s:4},{t:"Menggunakan data seadanya", s:3},{t:"Mendata sendiri tanpa melibatkan RT", s:2},{t:"Memalsukan data RT yang tidak melapor", s:1}], ex:"Koordinasi yang baik menyamakan pemahaman dan mendampingi, bukan mengganti atau melewati mitra."},
{id:"TKP-1354", q:"Bidan desa dan kader posyandu berselisih soal jadwal kegiatan sehingga program kesehatan terganggu. Anda diminta membantu. Anda akan ....", opts:[{t:"Mempertemukan keduanya, menyusun jadwal bersama yang disepakati, dan memantau pelaksanaannya", s:5},{t:"Memihak bidan desa sebagai tenaga profesional", s:4},{t:"Meminta keduanya menyelesaikan sendiri", s:3},{t:"Mengambil alih program posyandu", s:2},{t:"Membubarkan salah satu pihak", s:1}], ex:"Perselisihan mitra kerja diselesaikan dengan fasilitasi dan kesepakatan bersama."},
{id:"TKP-1355", q:"Tiga desa tetangga akan membangun jalan penghubung antar-desa dengan dana swadaya bersama. Peran terbaik perangkat desa Anda adalah ....", opts:[{t:"Aktif berkoordinasi membentuk panitia bersama, menyepakati pembagian biaya dan jadwal secara tertulis", s:5},{t:"Ikut serta bila desa lain sudah bergerak", s:4},{t:"Menunggu inisiatif dari kecamatan", s:3},{t:"Menolak karena menguntungkan desa lain juga", s:2},{t:"Memanfaatkan proyek untuk kepentingan pribadi", s:1}], ex:"Kerja sama antar-desa membutuhkan inisiatif koordinasi dan kesepakatan tertulis yang adil."},
{id:"TKP-1356", q:"Kecamatan meminta data kependudukan desa Anda dengan tenggat sangat mepet, padahal data belum rampung. Anda akan ....", opts:[{t:"Berkordinasi dengan perangkat lain membagi tugas pendataan, menyampaikan progres ke kecamatan, dan mengirim data tepat waktu", s:5},{t:"Mengirim data seadanya agar tenggat terpenuhi", s:4},{t:"Meminta perpanjangan tenggat ke kecamatan", s:3},{t:"Mengabaikan karena tenggat tidak realistis", s:2},{t:"Memalsukan data agar terlihat lengkap", s:1}], ex:"Tenggat mepet diatasi dengan pembagian tugas tim dan komunikasi progres, bukan data asal-asalan."},
{id:"TKP-1357", q:"Gotong royong perbaikan saluran irigasi sepi peserta karena warga sibuk. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Berkordinasi dengan kepala dusun dan tokoh masyarakat mengatur jadwal yang disepakati warga serta memberi contoh ikut turun langsung", s:5},{t:"Memerintahkan warga wajib ikut gotong royong", s:4},{t:"Membayar pekerja dengan dana desa", s:3},{t:"Membatalkan gotong royong", s:2},{t:"Menyalahkan warga yang tidak peduli", s:1}], ex:"Partisipasi warga digerakkan lewat kesepakatan jadwal dan keteladanan, bukan perintah."},
{id:"TKP-1358", q:"Dua perangkat desa berselisih paham hingga tidak saling bicara dan pelayanan terganggu. Anda sebagai rekan akan ....", opts:[{t:"Menjadi penengah, mendengarkan kedua belah pihak, dan membantu menemukan titik temu demi kelancaran pelayanan", s:5},{t:"Menasihati keduanya agar berdamai", s:4},{t:"Membiarkan hingga reda sendiri", s:3},{t:"Memihak salah satu pihak", s:2},{t:"Menyebarkan perselisihan itu ke warga", s:1}], ex:"Konflik internal yang mengganggu layanan harus difasilitasi penyelesaiannya, bukan dibiarkan."},
{id:"TKP-1359", q:"Musyawarah desa memanas karena dua kelompok warga ngotot dengan usulan masing-masing soal lokasi pembangunan. Sebagai fasilitator, Anda akan ....", opts:[{t:"Menengahi dengan data objektif, memberi kesempatan bicara bergiliran, dan mengarahkan pada voting atau kompromi yang disepakati", s:5},{t:"Memutuskan sendiri lokasi yang terbaik", s:4},{t:"Menunda musyawarah hingga suasana reda", s:3},{t:"Membubarkan musyawarah", s:2},{t:"Memihak kelompok yang lebih berpengaruh", s:1}], ex:"Fasilitator musyawarah menjaga keadilan bicara dan mengarahkan pada keputusan bersama berbasis data."},
{id:"TKP-1360", q:"Karang taruna ingin mengadakan turnamen sepak bola, tetapi perangkat desa keberatan memakai lapangan desa. Sikap terbaik adalah ....", opts:[{t:"Memfasilitasi kesepakatan pemakaian lapangan dengan jadwal dan tanggung jawab perawatan yang jelas", s:5},{t:"Mengizinkan dengan syarat ketat", s:4},{t:"Menolak demi menjaga lapangan", s:3},{t:"Membiarkan mereka memakai tanpa aturan", s:2},{t:"Menyewakan lapangan dengan tarif tinggi", s:1}], ex:"Aspirasi pemuda difasilitasi dengan aturan pakai yang jelas, bukan ditolak atau dibiarkan liar."},
{id:"TKP-1361", q:"PKK desa ingin mengadakan pelatihan keterampilan, tetapi tidak ada anggaran. Anda sebagai perangkat desa akan ....", opts:[{t:"Membantu PKK menyusun proposal, menghubungkan dengan dinas terkait atau CSR, dan memfasilitasi tempat kegiatan", s:5},{t:"Menyarankan PKK mencari dana sendiri", s:4},{t:"Menolak membantu karena tidak ada anggaran", s:3},{t:"Mengabaikan usulan PKK", s:2},{t:"Memakai dana desa diam-diam untuk kegiatan itu", s:1}], ex:"Keterbatasan anggaran diatasi dengan kreativitas menghubungkan ke sumber daya lain, bukan penolakan."},
{id:"TKP-1362", q:"Pendamping desa dari kabupaten memberikan arahan yang berbeda dengan kebiasaan perangkat desa soal pengelolaan dana desa. Anda akan ....", opts:[{t:"Mendiskusikan perbedaan itu secara terbuka dan mengikuti aturan resmi yang berlaku", s:5},{t:"Mengikuti arahan pendamping sepenuhnya", s:4},{t:"Tetap dengan kebiasaan lama", s:3},{t:"Mengabaikan pendamping desa", s:2},{t:"Melaporkan pendamping sebagai pengganggu", s:1}], ex:"Perbedaan pandangan diselesaikan lewat diskusi berbasis aturan, menghargai peran pendamping sebagai mitra."},
{id:"TKP-1363", q:"Babinsa dan Bhabinkamtibmas mengajak pemerintah desa patroli keamanan gabungan. Respons terbaik adalah ....", opts:[{t:"Menyambut baik, mengoordinasikan jadwal dengan RT/RW, dan ikut serta dalam pelaksanaannya", s:5},{t:"Menyetujui tetapi tidak ikut terlibat", s:4},{t:"Menolak dengan alasan kesibukan", s:3},{t:"Menganggap itu bukan urusan desa", s:2},{t:"Menolak karena merasa diawasi", s:1}], ex:"Sinergi dengan aparat keamanan memperkuat ketertiban desa; sambutan aktif adalah wujud kolaborasi."},
{id:"TKP-1364", q:"Pengurus BUMDes dan perangkat desa berbeda pendapat soal pembagian keuntungan usaha. Anda diminta menengahi. Anda akan ....", opts:[{t:"Mengacu pada AD/ART dan peraturan desa tentang BUMDes, lalu memfasilitasi kesepakatan yang adil", s:5},{t:"Memihak pengurus BUMDes sebagai pelaku usaha", s:4},{t:"Memihak perangkat desa sebagai pemilik modal", s:3},{t:"Membiarkan mereka bertengkar", s:2},{t:"Mengambil keuntungan untuk diri sendiri", s:1}], ex:"Sengketa kelembagaan diselesaikan dengan merujuk aturan yang disepakati, bukan pemihakan."},
{id:"TKP-1365", q:"Tim relawan bencana desa kekurangan personel saat banjir. Anda sebagai perangkat desa akan ....", opts:[{t:"Berkordinasi dengan karang taruna, RT/RW, dan Babinsa untuk pengerahan bersama serta pembagian tugas yang jelas", s:5},{t:"Mengandalkan relawan yang ada seadanya", s:4},{t:"Menunggu bantuan dari kabupaten", s:3},{t:"Menangani sendiri semampunya", s:2},{t:"Meninggalkan lokasi karena berbahaya", s:1}], ex:"Keadaan darurat membutuhkan pengerahan seluruh unsur desa secara terkoordinasi."},
{id:"TKP-1366", q:"Kasi pelayanan dan kasi kesejahteraan di kantor Anda berebut kewenangan mengurus program bantuan. Anda akan ....", opts:[{t:"Mengusulkan pembagian peran yang jelas sesuai tupoksi masing-masing dan disepakati bersama", s:5},{t:"Meminta kepala desa memutuskan", s:4},{t:"Membiarkan siapa yang paling agresif yang menang", s:3},{t:"Memihak salah satu kasi", s:2},{t:"Mengambil alih program untuk diri sendiri", s:1}], ex:"Ego sektoral diatasi dengan penegasan tupoksi yang disepakati, bukan perebutan."},
{id:"TKP-1367", q:"Rekan Anda akan cuti panjang dan menitipkan tugasnya tanpa penjelasan yang memadai. Anda akan ....", opts:[{t:"Memintanya membuat serah terima tertulis yang jelas agar pelayanan tidak terganggu selama ia cuti", s:5},{t:"Menerima titipan seadanya", s:4},{t:"Menolak menerima titipan tugas", s:3},{t:"Mengerjakan asal-asalan", s:2},{t:"Membiarkan tugasnya terbengkalai", s:1}], ex:"Serah terima tugas yang jelas adalah bentuk tanggung jawab kolaboratif agar layanan tetap berjalan."},
{id:"TKP-1368", q:"Rapat koordinasi perangkat desa sering tidak menghasilkan keputusan karena masing-masing bicara sendiri. Usulan perbaikan Anda adalah ....", opts:[{t:"Mengusulkan agenda tertulis, pembatasan waktu bicara, dan pencatatan keputusan beserta penanggung jawabnya", s:5},{t:"Mengusulkan rapat dipersingkat", s:4},{t:"Tidak ikut rapat lagi", s:3},{t:"Membiarkan rapat apa adanya", s:2},{t:"Memboikot rapat", s:1}], ex:"Rapat yang efektif butuh agenda, disiplin waktu, dan notulensi keputusan yang jelas."},
{id:"TKP-1369", q:"Tim Pelaksana Kegiatan (TPK) dana desa tidak melibatkan perangkat desa dalam pengawasan proyek. Anda akan ....", opts:[{t:"Berkordinasi dengan TPK untuk mekanisme pengawasan bersama yang transparan sesuai aturan", s:5},{t:"Mengawasi sendiri secara diam-diam", s:4},{t:"Membiarkan TPK bekerja sendiri", s:3},{t:"Menuduh TPK menyembunyikan sesuatu", s:2},{t:"Meminta jatah proyek ke TPK", s:1}], ex:"Pengawasan proyek desa adalah kerja bersama yang diatur mekanismenya, bukan saling curiga."},
{id:"TKP-1370", q:"Verifikasi penerima bantuan oleh perangkat desa dan RT hasilnya berbeda jauh. Tindak lanjut terbaik adalah ....", opts:[{t:"Melakukan verifikasi ulang bersama di lapangan hingga datanya disepakati kedua belah pihak", s:5},{t:"Memakai data versi perangkat desa", s:4},{t:"Memakai data versi RT", s:3},{t:"Menggabungkan kedua data apa adanya", s:2},{t:"Membuat data baru sendiri", s:1}], ex:"Perbedaan data diselesaikan dengan verifikasi bersama di lapangan, bukan adu klaim."},
{id:"TKP-1371", q:"Kepala dusun enggan berkoordinasi dengan kantor desa dan berjalan sendiri. Dampaknya pelayanan di dusun itu tersendat. Anda akan ....", opts:[{t:"Mengajaknya berdialog, mendengarkan keberatannya, dan membangun kembali pola koordinasi yang saling menguntungkan", s:5},{t:"Melaporkannya ke kepala desa untuk ditegur", s:4},{t:"Membiarkan dusun itu terpisah", s:3},{t:"Mengganti kepala dusun", s:2},{t:"Memutus komunikasi dengan dusun tersebut", s:1}], ex:"Hambatan koordinasi diatasi dengan dialog dan empati, bukan sanksi langsung."},
{id:"TKP-1372", q:"Program desa membutuhkan data dari puskesmas, tetapi puskesmas lambat merespons. Anda akan ....", opts:[{t:"Datang langsung berkoordinasi, menjelaskan kebutuhan dan tenggatnya, serta menawarkan bantuan pengolahan data", s:5},{t:"Mengirim surat permintaan resmi", s:4},{t:"Menunggu hingga puskesmas merespons", s:3},{t:"Membuat data perkiraan sendiri", s:2},{t:"Melaporkan puskesmas tidak kooperatif", s:1}], ex:"Koordinasi antar-instansi yang efektif bersifat proaktif dan solutif, bukan sekadar menunggu."},
{id:"TKP-1373", q:"Warga dari dua dusun bersaing tidak sehat soal lokasi pasar desa baru. Masing-masing mengklaim dusunnya paling layak. Anda akan ....", opts:[{t:"Memfasilitasi musyawarah dengan kriteria objektif (akses, luas lahan, jumlah penduduk) hingga disepakati bersama", s:5},{t:"Memutuskan berdasarkan pertimbangan kepala desa", s:4},{t:"Menunda pembangunan pasar", s:3},{t:"Memihak dusun yang lebih besar", s:2},{t:"Membatalkan rencana pasar desa", s:1}], ex:"Persaingan antar-wilayah diselesaikan dengan kriteria objektif yang disepakati, bukan keputusan sepihak."},
{id:"TKP-1374", q:"Kegiatan 17 Agustus di desa Anda kekurangan panitia. Anda sebagai perangkat desa akan ....", opts:[{t:"Berkordinasi dengan karang taruna, PKK, dan RT/RW membentuk panitia bersama dengan pembagian tugas jelas", s:5},{t:"Menangani sendiri semampunya", s:4},{t:"Membatalkan perayaan", s:3},{t:"Memaksa warga menjadi panitia", s:2},{t:"Menggunakan dana desa untuk menyewa EO", s:1}], ex:"Kegiatan bersama digerakkan dengan merangkul seluruh unsur masyarakat secara terorganisir."},
{id:"TKP-1375", q:"Laporan kegiatan perangkat desa sering tumpang tindih dan tidak sinkron. Perbaikan yang Anda usulkan adalah ....", opts:[{t:"Membuat format laporan terpadu dan jadwal pelaporan rutin yang disepakati semua perangkat", s:5},{t:"Meminta setiap perangkat memperbaiki laporannya sendiri", s:4},{t:"Membiarkan karena sudah terbiasa", s:3},{t:"Menghapus kewajiban laporan", s:2},{t:"Membuat laporan fiktif yang rapi", s:1}], ex:"Standardisasi format dan jadwal pelaporan menciptakan tertib administrasi kolektif."},
{id:"TKP-1376", q:"Seorang perangkat desa senior menolak memakai sistem administrasi baru dan tetap memakai cara lama. Anda akan ....", opts:[{t:"Mendampinginya belajar dengan sabar, menunjukkan manfaat sistem baru, hingga ia bisa menggunakannya", s:5},{t:"Memintanya belajar sendiri", s:4},{t:"Membiarkannya memakai cara lama", s:3},{t:"Melaporkannya sebagai pembangkang", s:2},{t:"Mengejeknya gaptek di depan rekan lain", s:1}], ex:"Perubahan sistem berhasil bila yang kesulitan didampingi dengan sabar, bukan dipaksa atau diejek."},
{id:"TKP-1377", q:"Dana swadaya pembangunan masjid desa tercampur dengan kas kegiatan desa lain. Bendahara bingung mempertanggungjawabkannya. Anda akan ....", opts:[{t:"Membantu memisahkan pencatatan tiap sumber dana secara jelas dan transparan", s:5},{t:"Menyarankan bendahara mencatat seadanya", s:4},{t:"Membiarkan tercampur", s:3},{t:"Memanfaatkan ketidakjelasan untuk kepentingan pribadi", s:2},{t:"Menuduh bendahara menyelewengkan dana", s:1}], ex:"Setiap sumber dana wajib dicatat terpisah agar pertanggungjawabannya jelas dan akuntabel."},
{id:"TKP-1378", q:"Kelompok tani dan kelompok nelayan di desa pesisir Anda berebut bantuan alat dari program desa. Anda akan ....", opts:[{t:"Memfasilitasi pembagian bantuan yang proporsional berdasarkan kebutuhan masing-masing kelompok", s:5},{t:"Memberi ke kelompok yang lebih dulu mengajukan", s:4},{t:"Memberi ke kelompok yang lebih besar", s:3},{t:"Menunda pemberian bantuan", s:2},{t:"Memberi ke kelompok yang dekat dengan perangkat desa", s:1}], ex:"Perebutan bantuan diselesaikan dengan pembagian proporsional berbasis kebutuhan."},
{id:"TKP-1379", q:"Acara adat dan rapat koordinasi perangkat desa dijadwalkan di balai desa pada waktu yang sama. Panitia adat sudah terlanjur menyebar undangan. Anda akan ....", opts:[{t:"Berkordinasi dengan panitia adat mencari solusi, misalnya menggeser rapat ke ruangan lain atau menyesuaikan waktu", s:5},{t:"Memaksa panitia adat pindah karena balai milik desa", s:4},{t:"Membatalkan rapat koordinasi", s:3},{t:"Membiarkan kedua acara berjalan bersamaan", s:2},{t:"Melarang acara adat di balai desa", s:1}], ex:"Benturan jadwal diselesaikan dengan musyawarah mencari solusi win-win, bukan pemaksaan."},
{id:"TKP-1380", q:"Evaluasi kinerja perangkat desa akan dilakukan. Sikap terbaik Anda menghadapinya adalah ....", opts:[{t:"Menyambut evaluasi sebagai bahan perbaikan dan menyampaikan capaian serta kendala secara jujur", s:5},{t:"Menerima evaluasi apa adanya", s:4},{t:"Berusaha tampil baik hanya saat evaluasi", s:3},{t:"Menolak dievaluasi", s:2},{t:"Memalsukan data capaian kinerja", s:1}], ex:"Evaluasi adalah sarana perbaikan; kejujuran dalam menyampaikannya menunjukkan profesionalisme."},
{id:"TKP-1381", q:"Dua keluarga besar di desa Anda bersengketa atas tanah ulayat yang diklaim sebagai warisan adat masing-masing. Mereka meminta pemerintah desa menjadi penengah. Anda akan ....", opts:[{t:"Memfasilitasi musyawarah dengan melibatkan tokoh adat, memeriksa bukti-bukti kedua belah pihak, dan mengarahkan pada kesepakatan tertulis", s:5},{t:"Menyerahkan sepenuhnya ke tokoh adat", s:4},{t:"Memutuskan sendiri berdasarkan arsip desa", s:3},{t:"Membiarkan mereka menyelesaikan sendiri", s:2},{t:"Memihak keluarga yang lebih berpengaruh", s:1}], ex:"Sengketa tanah adat diselesaikan lewat musyawarah yang melibatkan otoritas adat dan bukti, dengan hasil tertulis."},
{id:"TKP-1382", q:"Batas antara dua dusun dipersoalkan karena patok adatnya hilang dan masing-masing mengklaim wilayah kebun. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Memfasilitasi pengukuran ulang bersama kedua dusun dengan saksi tokoh adat dan menuangkannya dalam berita acara", s:5},{t:"Menetapkan batas berdasarkan ingatan sesepuh satu dusun", s:4},{t:"Membiarkan status quo", s:3},{t:"Menyerahkan ke pengadilan", s:2},{t:"Menetapkan batas yang menguntungkan dusun sendiri", s:1}], ex:"Sengketa batas diselesaikan dengan pengukuran bersama yang disaksikan dan didokumentasikan resmi."},
{id:"TKP-1383", q:"Hukum adat setempat tidak mengakui hak waris anak perempuan, padahal hukum nasional menjaminnya. Seorang ahli waris perempuan meminta surat keterangan waris. Anda akan ....", opts:[{t:"Menerbitkan surat sesuai hukum nasional yang berlaku sambil menjelaskan dengan bijak kepada keluarga besar", s:5},{t:"Menerbitkan surat sesuai hukum adat setempat", s:4},{t:"Menolak menerbitkan surat", s:3},{t:"Menyuruhnya menggugat ke pengadilan", s:2},{t:"Memalsukan surat sesuai keinginan keluarga laki-laki", s:1}], ex:"Hukum nasional yang menjamin kesetaraan berlaku di atas ketentuan adat yang diskriminatif."},
{id:"TKP-1384", q:"Tokoh adat melarang warganya menghadiri musrenbang desa karena dianggap tidak sesuai adat. Padahal kehadiran warga penting. Anda akan ....", opts:[{t:"Bersilaturahmi ke tokoh adat, menjelaskan tujuan musrenbang dengan bahasa yang menghormati adat, dan mencari titik temu", s:5},{t:"Memaksa warga tetap hadir", s:4},{t:"Membatalkan musrenbang", s:3},{t:"Mengabaikan larangan tokoh adat", s:2},{t:"Melaporkan tokoh adat sebagai penghalang pembangunan", s:1}], ex:"Pendekatan persuasif yang menghormati tokoh adat lebih efektif daripada pemaksaan."},
{id:"TKP-1385", q:"Upacara adat yang melibatkan penutupan jalan desa seharian memicu protes warga yang butuh lewat. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Memfasilitasi kesepakatan antara panitia adat dan warga soal durasi penutupan dan jalur alternatif", s:5},{t:"Mengizinkan penutupan penuh demi adat", s:4},{t:"Melarang upacara adat menutup jalan", s:3},{t:"Membiarkan protes berlangsung", s:2},{t:"Memihak warga yang protes dan membubarkan upacara", s:1}], ex:"Tradisi dihormati dan kepentingan umum dilindungi lewat kesepakatan yang adil bagi semua."},
{id:"TKP-1386", q:"Kelompok minoritas agama di desa Anda ingin membangun rumah ibadah, tetapi sebagian warga menolak. Anda akan ....", opts:[{t:"Memfasilitasi dialog, menjelaskan hak beribadah yang dijamin konstitusi dan aturan pendirian rumah ibadah, serta mencari solusi bersama", s:5},{t:"Menunda pembangunan hingga suasana reda", s:4},{t:"Melarang pembangunan demi kerukunan", s:3},{t:"Membiarkan penolakan warga", s:2},{t:"Ikut menolak pembangunan rumah ibadah", s:1}], ex:"Kebebasan beribadah adalah hak konstitusional; penolakan diselesaikan lewat dialog berbasis aturan."},
{id:"TKP-1387", q:"Warga pendatang dari daerah lain sering dipersulit mengurus administrasi dan dilarang ikut kegiatan desa. Anda akan ....", opts:[{t:"Menegaskan bahwa semua warga berdomisili berhak atas layanan dan kegiatan desa, serta mensosialisasikannya ke RT/RW", s:5},{t:"Meminta pendatang bersabar beradaptasi", s:4},{t:"Membiarkan perlakuan itu", s:3},{t:"Mendukung pembatasan untuk pendatang", s:2},{t:"Ikut mempersulit urusan pendatang", s:1}], ex:"Diskriminasi terhadap pendatang bertentangan dengan prinsip persatuan dan pelayanan yang adil."},
{id:"TKP-1388", q:"Sebagian warga lansia tidak paham penjelasan petugas yang berbahasa Indonesia formal. Dalam pelayanan, Anda akan ....", opts:[{t:"Menjelaskan dengan bahasa daerah yang mereka pahami sambil tetap tertib administrasi", s:5},{t:"Tetap memakai bahasa Indonesia formal", s:4},{t:"Meminta warga membawa penerjemah keluarga", s:3},{t:"Mengabaikan yang tidak paham", s:2},{t:"Menertawakan logat mereka", s:1}], ex:"Bahasa daerah adalah jembatan pelayanan; memakainya menunjukkan empati tanpa mengurangi tertib administrasi."},
{id:"TKP-1389", q:"Pasangan yang menikah secara adat belum mencatatkan pernikahannya sehingga anaknya kesulitan mendapat akta kelahiran. Anda akan ....", opts:[{t:"Membantu memfasilitasi pencatatan pernikahan dan pengurusan akta kelahiran anaknya sesuai prosedur", s:5},{t:"Menyarankan mencatatkan pernikahan saja", s:4},{t:"Membiarkan karena itu pilihan mereka", s:3},{t:"Menolak membantu pengurusan akta", s:2},{t:"Menyalahkan mereka tidak tertib administrasi", s:1}], ex:"Perangkat desa proaktif membantu warga memenuhi tertib administrasi kependudukan."},
{id:"TKP-1390", q:"Adat setempat melarang kegiatan di hari tertentu, padahal ada pelayanan administrasi mendesak yang harus berjalan. Sikap Anda adalah ....", opts:[{t:"Menghormati adat dengan menyesuaikan jadwal, namun tetap membuka layanan darurat untuk keperluan mendesak", s:5},{t:"Menutup total pelayanan mengikuti adat", s:4},{t:"Mengabaikan larangan adat", s:3},{t:"Memaksa warga melanggar adatnya", s:2},{t:"Mengejek kepercayaan adat warga", s:1}], ex:"Penghormatan pada adat diimbangi dengan jaminan layanan darurat tetap tersedia."},
{id:"TKP-1391", q:"Dua warga berselisih dan tokoh adat menawarkan penyelesaian secara adat yang disetujui kedua belah pihak. Peran Anda sebagai perangkat desa adalah ....", opts:[{t:"Mendukung dan memfasilitasi penyelesaian adat, serta mencatat hasilnya sebagai dokumen resmi", s:5},{t:"Membiarkan proses adat berjalan sendiri", s:4},{t:"Menolak karena harus lewat jalur formal", s:3},{t:"Mengambil alih penyelesaian", s:2},{t:"Mengadu domba kedua belah pihak", s:1}], ex:"Penyelesaian adat yang disepakati para pihak dihormati dan didokumentasikan resmi."},
{id:"TKP-1392", q:"Perayaan hari besar keagamaan minoritas di desa Anda diganggu sekelompok warga. Anda akan ....", opts:[{t:"Menjamin keamanan perayaan dengan berkoordinasi aparat dan tokoh masyarakat, serta menindak pengganggu sesuai aturan", s:5},{t:"Meminta perayaan dilakukan tertutup saja", s:4},{t:"Membiarkan gangguan itu", s:3},{t:"Melarang perayaan minoritas", s:2},{t:"Ikut mengganggu perayaan", s:1}], ex:"Negara wajib menjamin keamanan ibadah semua pemeluk agama tanpa kecuali."},
{id:"TKP-1393", q:"Program pemerintah mewajibkan pendataan digital, tetapi tetua adat khawatir data adat disalahgunakan. Anda akan ....", opts:[{t:"Menjelaskan tujuan dan jaminan keamanan data dengan bahasa yang menghormati, serta meminta persetujuan sebelum mendata", s:5},{t:"Tetap mendata tanpa penjelasan", s:4},{t:"Melewatkan wilayah adat itu", s:3},{t:"Memaksa pendataan", s:2},{t:"Memalsukan data wilayah adat", s:1}], ex:"Kekhawatiran tokoh adat dijawab dengan penjelasan transparan dan persetujuan, bukan pemaksaan."},
{id:"TKP-1394", q:"Kesenian tradisional desa terancam punah karena tidak ada regenerasi. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Mengusulkan pelestarian lewat sanggar, ekstrakurikuler sekolah, dan festival desa dengan dukungan anggaran", s:5},{t:"Mengimbau warga melestarikan", s:4},{t:"Membiarkan punah secara alami", s:3},{t:"Mengganti dengan kesenian modern", s:2},{t:"Mengejek kesenian tradisional ketinggalan zaman", s:1}], ex:"Pelestarian budaya butuh langkah konkret: wadah, regenerasi, dan dukungan anggaran."},
{id:"TKP-1395", q:"Musyawarah adat memutuskan sesuatu yang bertentangan dengan peraturan desa yang sudah ditetapkan. Anda akan ....", opts:[{t:"Memfasilitasi dialog antara tokoh adat dan pemerintah desa untuk menyelaraskan kedua keputusan", s:5},{t:"Mengikuti keputusan adat", s:4},{t:"Mengikuti peraturan desa secara kaku", s:3},{t:"Mengabaikan salah satunya", s:2},{t:"Mengadu domba kedua belah pihak", s:1}], ex:"Pertentangan norma diselesaikan lewat dialog penyelarasan, bukan penegasian sepihak."},
{id:"TKP-1396", q:"Gotong royong adat membersihkan makam leluhur bentrok dengan jadwal kerja bakti desa. Anda akan ....", opts:[{t:"Menggabungkan atau menyesuaikan jadwal agar kedua kegiatan bisa berjalan tanpa mengorbankan salah satunya", s:5},{t:"Memprioritaskan kerja bakti desa", s:4},{t:"Memprioritaskan gotong royong adat", s:3},{t:"Membatalkan salah satunya", s:2},{t:"Melarang gotong royong adat", s:1}], ex:"Kegiatan adat dan program desa diselaraskan, bukan dipertentangkan."},
{id:"TKP-1397", q:"Larangan adat menebang pohon di hutan tertentu dilanggar oleh warga untuk kebutuhan mendesak. Tokoh adat meminta sanksi adat, warga meminta keringanan. Anda akan ....", opts:[{t:"Memfasilitasi musyawarah antara tokoh adat dan warga untuk sanksi yang adil disertai solusi kebutuhan kayunya", s:5},{t:"Menyerahkan sepenuhnya ke sanksi adat", s:4},{t:"Membela warga yang melanggar", s:3},{t:"Mengabaikan pelanggaran", s:2},{t:"Melaporkan warga ke polisi", s:1}], ex:"Pelanggaran norma adat diselesaikan lewat musyawarah yang adil bagi pelanggar sekaligus menjaga kelestarian."},
{id:"TKP-1398", q:"Pembagian air irigasi antar-kelompok tani memicu konflik karena aturan adat pembagian dianggap tidak adil oleh kelompok hilir. Anda akan ....", opts:[{t:"Memfasilitasi musyawarah dengan data kebutuhan tiap kelompok hingga disepakati jadwal pembagian yang adil", s:5},{t:"Mempertahankan aturan adat apa adanya", s:4},{t:"Memihak kelompok hulu yang lebih kuat", s:3},{t:"Membiarkan konflik", s:2},{t:"Menutup saluran irigasi", s:1}], ex:"Konflik sumber daya diselesaikan dengan musyawarah berbasis data kebutuhan yang adil."},
{id:"TKP-1399", q:"Rencana proyek desa melewati kawasan hutan adat yang disakralkan warga. Mereka menolak keras. Anda akan ....", opts:[{t:"Mengusulkan peninjauan ulang rute proyek dengan melibatkan tokoh adat dan kajian dampaknya", s:5},{t:"Tetap melaksanakan proyek demi pembangunan", s:4},{t:"Membatalkan proyek sepihak", s:3},{t:"Memaksa warga menerima", s:2},{t:"Menyuap tokoh adat agar setuju", s:1}], ex:"Kawasan sakral dihormati; proyek dikaji ulang rutenya dengan melibatkan pemangku adat."},
{id:"TKP-1400", q:"Seorang warga beda suku diejek dan dikucilkan dalam kegiatan desa. Anda menyaksikannya. Sikap Anda adalah ....", opts:[{t:"Menegur pelaku, merangkul warga tersebut, dan mengampanyekan keberagaman dalam kegiatan desa", s:5},{t:"Menasihati pelaku secara pribadi", s:4},{t:"Diam karena takut ikut dimusuhi", s:3},{t:"Membiarkan karena sudah biasa", s:2},{t:"Ikut mengejek", s:1}], ex:"Diskriminasi suku wajib dilawan secara terbuka dengan keteladanan inklusif."},
{id:"TKP-1401", q:"Pernikahan beda adat antara dua warga memicu penolakan keluarga besar kedua belah pihak. Mereka meminta mediasi pemerintah desa. Anda akan ....", opts:[{t:"Memfasilitasi dialog keluarga dengan menghormati kedua adat dan mengarahkan pada kesepakatan yang membahagiakan pasangan", s:5},{t:"Memihak adat yang lebih dominan", s:4},{t:"Menolak memediasi", s:3},{t:"Melarang pernikahan itu", s:2},{t:"Mengadu domba kedua keluarga", s:1}], ex:"Mediasi perkawinan beda adat menjembatani kedua tradisi dengan mengutamakan kebahagiaan pasangan."},
{id:"TKP-1402", q:"Bahasa daerah di desa Anda mulai jarang dipakai generasi muda. Upaya pelestarian terbaik yang bisa diusulkan perangkat desa adalah ....", opts:[{t:"Mengusulkan muatan lokal bahasa daerah di sekolah dan lomba pidato bahasa daerah tingkat desa", s:5},{t:"Mengimbau orang tua mengajarkan di rumah", s:4},{t:"Membiarkan perkembangan zaman", s:3},{t:"Melarang pemakaian bahasa Indonesia di desa", s:2},{t:"Mengejek generasi muda yang tidak bisa bahasa daerah", s:1}], ex:"Pelestarian bahasa butuh program terstruktur di sekolah dan ruang publik, bukan sekadar imbauan."},
{id:"TKP-1403", q:"Ritual adat kematian mengharuskan keluarga menanggung biaya besar hingga berutang. Seorang warga mengeluh ke Anda. Anda akan ....", opts:[{t:"Memfasilitasi dialog dengan tokoh adat untuk penyederhanaan ritual tanpa menghilangkan maknanya", s:5},{t:"Menyarankan warga mengikuti saja", s:4},{t:"Melarang ritual adat itu", s:3},{t:"Mengabaikan keluhan", s:2},{t:"Mengejek adat yang memberatkan", s:1}], ex:"Beban adat yang memberatkan disikapi dengan dialog penyederhanaan yang menghormati makna ritual."},
{id:"TKP-1404", q:"Anak angkat menurut adat setempat tidak diakui dalam pembagian waris keluarga angkatnya dan kini menuntut keadilan. Anda akan ....", opts:[{t:"Memfasilitasi musyawarah keluarga dengan menjelaskan hak anak angkat menurut hukum nasional", s:5},{t:"Mengikuti ketentuan adat setempat", s:4},{t:"Menolak terlibat", s:3},{t:"Memihak keluarga angkat", s:2},{t:"Memalsukan dokumen waris", s:1}], ex:"Hak keperdataan warga dilindungi hukum nasional sekalipun adat setempat belum mengakuinya."},
{id:"TKP-1405", q:"Kelompok pengajian ibu-ibu dan kelompok pemuda berselisih soal penggunaan balai desa. Anda akan ....", opts:[{t:"Memfasilitasi penyusunan jadwal pakai bersama yang adil dan disepakati kedua kelompok", s:5},{t:"Memberi prioritas ke kelompok pengajian", s:4},{t:"Memberi prioritas ke kelompok pemuda", s:3},{t:"Melarang keduanya memakai balai", s:2},{t:"Memihak kelompok yang dekat dengan Anda", s:1}], ex:"Fasilitas publik dibagi adil lewat jadwal bersama yang disepakati, tanpa pemihakan."},
{id:"TKP-1406", q:"Tradisi pernikahan dini masih kuat di desa Anda meski melanggar batas usia perkawinan. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Mengedukasi warga tentang dampak dan aturan batas usia perkawinan lewat tokoh agama, adat, dan kesehatan", s:5},{t:"Melarang keras tanpa edukasi", s:4},{t:"Membiarkan karena tradisi", s:3},{t:"Membantu memalsukan usia di dokumen", s:2},{t:"Mendukung tradisi itu", s:1}], ex:"Tradisi yang merugikan diubah lewat edukasi kolaboratif dengan para tokoh, bukan pelarangan kaku."},
{id:"TKP-1407", q:"Warga transmigran dan warga lokal berselisih soal giliran memakai balai pertemuan. Anda akan ....", opts:[{t:"Menegaskan balai milik seluruh warga dan memfasilitasi jadwal bersama yang setara", s:5},{t:"Memprioritaskan warga lokal", s:4},{t:"Memprioritaskan transmigran", s:3},{t:"Membiarkan mereka berebut", s:2},{t:"Melarang transmigran memakai balai", s:1}], ex:"Fasilitas desa adalah milik bersama tanpa diskriminasi asal-usul."},
{id:"TKP-1408", q:"Upacara adat panen membutuhkan iuran wajib yang memberatkan warga miskin. Anda akan ....", opts:[{t:"Mengusulkan iuran sukarela berjenjang sesuai kemampuan lewat musyawarah adat", s:5},{t:"Memaksa semua membayar sama", s:4},{t:"Membebaskan warga miskin sepihak tanpa musyawarah", s:3},{t:"Membatalkan upacara adat", s:2},{t:"Menarik iuran paksa dari warga miskin", s:1}], ex:"Beban iuran adat disesuaikan kemampuan lewat musyawarah agar tidak memberatkan yang miskin."},
{id:"TKP-1409", q:"Seorang tokoh agama dan tokoh adat berselisih soal tata cara pemakaman warga. Keluarga almarhum bingung. Anda akan ....", opts:[{t:"Memfasilitasi keduanya menghormati keinginan keluarga almarhum sebagai penentu utama", s:5},{t:"Memihak tokoh agama", s:4},{t:"Memihak tokoh adat", s:3},{t:"Membiarkan perselisihan", s:2},{t:"Mengambil alih pemakaman", s:1}], ex:"Keinginan keluarga yang berduka adalah yang utama; para tokoh difasilitasi untuk menghormatinya."},
{id:"TKP-1410", q:"Pelestarian rumah adat desa membutuhkan dana besar sementara APBDes terbatas. Solusi terbaik adalah ....", opts:[{t:"Mengusulkan skema gotong royong, mengajukan bantuan ke dinas kebudayaan, dan menggalang donasi secara transparan", s:5},{t:"Memakai seluruh dana desa untuk itu", s:4},{t:"Membiarkan rumah adat rusak", s:3},{t:"Menjual artefak adat untuk dana", s:2},{t:"Merobohkan dan membangun yang modern", s:1}], ex:"Pelestarian cagar budaya didanai lewat kombinasi swadaya, bantuan pemerintah, dan donasi transparan."},
{id:"TKP-1411", q:"Anda diminta menginput data keuangan desa ke aplikasi Siskeudes tetapi belum pernah menggunakannya. Sikap Anda adalah ....", opts:[{t:"Mempelajari panduan dan meminta bimbingan operator yang sudah bisa hingga mampu mengoperasikannya", s:5},{t:"Mencoba-coba sendiri hingga bisa", s:4},{t:"Meminta orang lain mengerjakan", s:3},{t:"Mengisi asal-asalan", s:2},{t:"Menolak memakai aplikasi", s:1}], ex:"Adaptasi teknologi adalah tuntutan ASN; belajar aktif hingga mampu adalah sikap yang benar."},
{id:"TKP-1412", q:"Website desa sudah lama tidak diperbarui sehingga informasinya kedaluwarsa. Sebagai pengelola, Anda akan ....", opts:[{t:"Memperbarui konten secara berkala: pengumuman, APBDes, agenda desa, dan potensi BUMDes", s:5},{t:"Memperbarui bila ada waktu luang", s:4},{t:"Membiarkan apa adanya", s:3},{t:"Menutup website desa", s:2},{t:"Mengisi website dengan konten pribadi", s:1}], ex:"Website desa adalah etalase transparansi; kontennya wajib mutakhir dan informatif."},
{id:"TKP-1413", q:"Foto KTP dan KK warga diunggah oleh oknum perangkat desa ke media sosial sebagai bahan candaan. Anda mengetahuinya. Anda akan ....", opts:[{t:"Meminta pengunggah menghapusnya segera dan melaporkannya karena melanggar perlindungan data pribadi", s:5},{t:"Meminta pengunggah menghapusnya", s:4},{t:"Membiarkan karena sudah terlanjur viral", s:3},{t:"Ikut menyebarkan", s:2},{t:"Mengunggah data warga lain", s:1}], ex:"Data pribadi warga dilindungi undang-undang; penyebarannya wajib dihentikan dan dilaporkan."},
{id:"TKP-1414", q:"Beredar hoaks di grup WhatsApp warga bahwa akan ada bantuan tunai besar-besaran dan warga diminta mengumpulkan fotokopi KTP ke seseorang. Anda akan ....", opts:[{t:"Segera mengklarifikasi lewat kanal resmi desa, mengimbau warga tidak menyerahkan dokumen, dan melaporkan penyebar hoaks", s:5},{t:"Menginformasikan bahwa kabar itu tidak benar", s:4},{t:"Membiarkan karena bukan urusan desa", s:3},{t:"Ikut menyebarkan kabar itu", s:2},{t:"Memanfaatkan situasi untuk mengumpulkan data warga", s:1}], ex:"Hoaks yang mengincar data warga harus diklarifikasi cepat lewat kanal resmi dan pelakunya dilaporkan."},
{id:"TKP-1415", q:"Pendaftaran bantuan sosial kini wajib online, tetapi banyak warga dusun terpencil tidak ada sinyal dan tidak punya ponsel pintar. Anda akan ....", opts:[{t:"Membuka posko bantuan pendaftaran di balai desa/dusun dengan perangkat dan pendampingan petugas", s:5},{t:"Meminta warga ke kota untuk mendaftar", s:4},{t:"Membiarkan warga yang tidak bisa mendaftar", s:3},{t:"Mendaftarkan warga dengan data asal-asalan", s:2},{t:"Memungut biaya pendaftaran online", s:1}], ex:"Digitalisasi layanan tidak boleh mengecualikan warga yang terkendala teknologi; posko bantuan adalah solusinya."},
{id:"TKP-1416", q:"Seorang lansia kebingungan mengisi formulir pendaftaran online di ponselnya dan meminta bantuan Anda. Anda akan ....", opts:[{t:"Membantunya mengisi dengan sabar sambil menjelaskan tiap langkah agar ia paham", s:5},{t:"Mengisikan langsung tanpa penjelasan", s:4},{t:"Memintanya meminta bantuan anaknya", s:3},{t:"Menolak membantu", s:2},{t:"Mengejeknya gaptek", s:1}], ex:"Pendampingan digital bagi lansia dilakukan dengan sabar sekaligus mengedukasi."},
{id:"TKP-1417", q:"Password akun Siskeudes desa diketahui banyak orang karena sering dibagikan. Sebagai pengelola, Anda akan ....", opts:[{t:"Mengganti password, membatasi akses sesuai kewenangan, dan mensosialisasikan keamanan akun", s:5},{t:"Mengganti password saja", s:4},{t:"Membiarkan karena memudahkan kerja", s:3},{t:"Membagikan ke lebih banyak orang", s:2},{t:"Menggunakan akun itu untuk kepentingan pribadi", s:1}], ex:"Keamanan akun sistem keuangan negara wajib dijaga dengan akses terbatas dan password yang dirahasiakan."},
{id:"TKP-1418", q:"Warga menerima pesan mengatasnamakan program bansos yang meminta kode OTP untuk pencairan. Ia bertanya kepada Anda. Anda akan ....", opts:[{t:"Menegaskan itu penipuan, mengimbau tidak memberikan OTP ke siapa pun, dan mensosialisasikan ke seluruh warga", s:5},{t:"Menyarankan mengabaikan pesan itu", s:4},{t:"Tidak tahu dan tidak peduli", s:3},{t:"Menyarankan mengikuti instruksi pesan", s:2},{t:"Ikut meminta OTP warga", s:1}], ex:"Edukasi anti-phishing adalah bagian perlindungan warga di era digital."},
{id:"TKP-1419", q:"Arsip digital dokumen desa hanya tersimpan di satu laptop tanpa cadangan. Tindakan pencegahan terbaik adalah ....", opts:[{t:"Membuat backup rutin di media penyimpanan berbeda dan menyusun sistem pengarsipan yang tertib", s:5},{t:"Menyalin sesekali ke flashdisk", s:4},{t:"Membiarkan karena laptop masih bagus", s:3},{t:"Menghapus arsip lama agar ringan", s:2},{t:"Menyimpan arsip di laptop pribadi tanpa pengaman", s:1}], ex:"Arsip negara wajib dicadangkan dan ditata agar tidak hilang dan mudah ditemukan."},
{id:"TKP-1420", q:"Kecamatan mengadakan rapat koordinasi via video conference, tetapi jaringan di kantor desa tidak stabil. Anda akan ....", opts:[{t:"Mempersiapkan jauh hari: uji koneksi, siapkan alternatif tethering, dan datang lebih awal", s:5},{t:"Bergabung apa adanya", s:4},{t:"Tidak ikut dengan alasan sinyal", s:3},{t:"Meminta rapat dibatalkan", s:2},{t:"Berpura-pura ikut padahal tidak", s:1}], ex:"Kendala teknis diantisipasi dengan persiapan, bukan dijadikan alasan absen."},
{id:"TKP-1421", q:"Rekaman CCTV balai desa yang menampilkan warga sedang mengurus surat disebarluaskan tanpa izin. Anda akan ....", opts:[{t:"Meminta penyebar menghapusnya dan menegaskan rekaman CCTV hanya untuk keamanan, bukan konsumsi publik", s:5},{t:"Meminta penyebar menghapusnya", s:4},{t:"Membiarkan", s:3},{t:"Ikut menyebarkan", s:2},{t:"Memasang lebih banyak CCTV di ruang privat", s:1}], ex:"Rekaman pengawasan memiliki batas privasi; penyebarannya tanpa izin wajib dihentikan."},
{id:"TKP-1422", q:"Ditemukan data ganda penerima bantuan dalam sistem digital desa. Tindak lanjut Anda adalah ....", opts:[{t:"Memverifikasi ke lapangan bersama RT/RW, membersihkan data ganda, dan memperbaiki proses inputnya", s:5},{t:"Menghapus salah satu data ganda", s:4},{t:"Membiarkan karena sistem yang salah", s:3},{t:"Memanfaatkan data ganda untuk kerabat", s:2},{t:"Menuduh operator memanipulasi", s:1}], ex:"Data ganda diselesaikan dengan verifikasi lapangan dan perbaikan sistem, bukan penghapusan asal."},
{id:"TKP-1423", q:"Desa Anda ingin mengadakan pelatihan literasi digital untuk lansia. Rancangan terbaik adalah ....", opts:[{t:"Materi sederhana dan praktik langsung: memakai ponsel, mengenali hoaks dan penipuan, dengan pendampingan sabar", s:5},{t:"Ceramah teori tentang internet", s:4},{t:"Membagikan brosur saja", s:3},{t:"Membatalkan karena lansia sulit diajari", s:2},{t:"Mengadakan pelatihan fiktif untuk laporan", s:1}], ex:"Literasi digital lansia efektif lewat praktik langsung yang sederhana dan pendampingan sabar."},
{id:"TKP-1424", q:"Surat-menyurat desa akan beralih ke tanda tangan elektronik, tetapi sebagian perangkat meragukan keabsahannya. Anda akan ....", opts:[{t:"Menjelaskan dasar hukum dan keabsahannya serta mendampingi hingga semua terbiasa", s:5},{t:"Memaksa semua menggunakannya", s:4},{t:"Tetap memakai tanda tangan basah", s:3},{t:"Menolak peralihan", s:2},{t:"Memalsukan tanda tangan elektronik atasan", s:1}], ex:"Transformasi digital berhasil lewat edukasi dan pendampingan, bukan pemaksaan."},
{id:"TKP-1425", q:"Warga ingin menyampaikan pengaduan lewat pesan WhatsApp resmi desa di luar jam kerja. Kebijakan terbaik adalah ....", opts:[{t:"Menyediakan balasan otomatis bahwa pesan akan ditindaklanjuti pada jam kerja, dan benar-benar menindaklanjutinya", s:5},{t:"Membalas seadanya", s:4},{t:"Mengabaikan pesan di luar jam kerja", s:3},{t:"Memblokir warga yang mengirim di luar jam kerja", s:2},{t:"Menonaktifkan nomor pengaduan", s:1}], ex:"Kanal pengaduan digital dikelola dengan kepastian tindak lanjut, bukan diabaikan."},
{id:"TKP-1426", q:"Basis data kependudukan desa diretas dan diduga bocor. Langkah pertama Anda adalah ....", opts:[{t:"Melaporkan insiden ke atasan dan pihak berwenang, mengamankan sistem, dan menginformasikan warga secara transparan", s:5},{t:"Menyembunyikan kejadian agar tidak panik", s:4},{t:"Membiarkan karena bukan ahli IT", s:3},{t:"Menyalahkan operator", s:2},{t:"Memanfaatkan kebocoran untuk kepentingan pribadi", s:1}], ex:"Insiden kebocoran data ditangani terbuka: lapor, amankan, dan informasikan warga."},
{id:"TKP-1427", q:"BUMDes ingin mempromosikan produknya di media sosial. Saran terbaik Anda sebagai perangkat desa adalah ....", opts:[{t:"Membuat konten jujur dan menarik, mencantumkan informasi yang benar, dan merespons pelanggan dengan ramah", s:5},{t:"Membuat akun dan mengunggah seadanya", s:4},{t:"Membeli follower agar terlihat ramai", s:3},{t:"Membuat klaim berlebihan agar laris", s:2},{t:"Menjiplak konten usaha lain", s:1}], ex:"Promosi digital BUMDes harus jujur, informatif, dan dikelola profesional."},
{id:"TKP-1428", q:"Sistem informasi desa error saat warga membutuhkan surat mendesak. Anda akan ....", opts:[{t:"Melayani manual sementara, mencatatnya, dan melaporkan error ke pengelola sistem untuk diperbaiki", s:5},{t:"Meminta warga menunggu sistem pulih", s:4},{t:"Menolak melayani hingga sistem normal", s:3},{t:"Menyalahkan pengelola sistem", s:2},{t:"Memanipulasi sistem agar terlihat normal", s:1}], ex:"Gangguan sistem tidak boleh menghentikan pelayanan; layanan manual sementara adalah solusinya."},
{id:"TKP-1429", q:"Seorang warga meminta Anda menghapus data tunggakan iuran di sistem desa dengan imbalan. Anda akan ....", opts:[{t:"Menolak tegas karena memanipulasi data sistem adalah pelanggaran", s:5},{t:"Menolak dengan halus", s:4},{t:"Mempertimbangkan karena imbalannya besar", s:3},{t:"Menghapus data dan menerima imbalan", s:2},{t:"Menghapus data lalu memeras warga itu", s:1}], ex:"Integritas data sistem tidak bisa ditukar dengan imbalan apa pun."},
{id:"TKP-1430", q:"Penggunaan grup WhatsApp resmi desa sebaiknya diatur dengan ....", opts:[{t:"Aturan grup yang jelas: hanya info resmi, dilarang hoaks, ujaran kebencian, dan promosi pribadi", s:5},{t:"Aturan lisan seadanya", s:4},{t:"Tanpa aturan", s:3},{t:"Membiarkan semua konten", s:2},{t:"Memakai grup untuk kampanye pribadi", s:1}], ex:"Grup resmi desa butuh tata tertib tertulis agar tetap menjadi kanal informasi yang sehat."},
{id:"TKP-1431", q:"Seorang penceramah di masjid desa menyampaikan ceramah yang memprovokasi kebencian terhadap kelompok agama lain. Sebagai perangkat desa, Anda akan ....", opts:[{t:"Berkordinasi dengan takmir masjid dan tokoh agama untuk menegur penceramah serta melaporkan konten provokatif ke pihak berwenang", s:5},{t:"Menegur penceramah secara pribadi", s:4},{t:"Diam karena takut dituduh anti-Islam", s:3},{t:"Membiarkan karena kebebasan berceramah", s:2},{t:"Ikut menyebarkan ceramah provokatif itu", s:1}], ex:"Provokasi kebencian atas nama agama wajib dicegah lewat koordinasi tokoh dan pelaporan resmi."},
{id:"TKP-1432", q:"Di grup WhatsApp karang taruna beredar konten yang mengagungkan sistem khilafah dan merendahkan Pancasila. Anda mengetahuinya. Anda akan ....", opts:[{t:"Mengedukasi anggota grup tentang bahaya paham tersebut dan melaporkan penyebar konten ke pihak berwenang", s:5},{t:"Mengingatkan anggota grup agar tidak menyebar", s:4},{t:"Keluar dari grup", s:3},{t:"Membiarkan karena hanya diskusi", s:2},{t:"Ikut menyebarkan konten itu", s:1}], ex:"Paham yang menentang dasar negara harus dilawan dengan edukasi dan pelaporan."},
{id:"TKP-1433", q:"Ada indikasi perekrutan paham ekstrem lewat kegiatan pengajian tertutup di desa Anda. Tindakan terbaik adalah ....", opts:[{t:"Berkordinasi dengan tokoh agama, Babinsa, dan Bhabinkamtibmas untuk memantau dan melakukan pembinaan", s:5},{t:"Meminta pengajian itu dibubarkan", s:4},{t:"Mengawasi diam-diam sendiri", s:3},{t:"Mengabaikan karena belum ada bukti", s:2},{t:"Ikut dalam pengajian itu", s:1}], ex:"Indikasi radikalisme ditangani lewat koordinasi aparat dan pembinaan tokoh agama, bukan main hakim sendiri."},
{id:"TKP-1434", q:"Sebagian warga menolak pembangunan tempat ibadah minoritas dengan dalih menjaga kemurnian akidah warga. Anda akan ....", opts:[{t:"Menegaskan hak beribadah dijamin konstitusi, memfasilitasi dialog, dan memastikan proses perizinan berjalan adil", s:5},{t:"Menunda pembangunan", s:4},{t:"Melarang pembangunan", s:3},{t:"Membiarkan penolakan", s:2},{t:"Ikut menolak", s:1}], ex:"Intoleransi atas nama agama tidak boleh mengalahkan hak konstitusional warga."},
{id:"TKP-1435", q:"Ujaran kebencian bernuansa suku beredar di media sosial warga desa dan memicu ketegangan. Anda akan ....", opts:[{t:"Mengimbau warga tidak terprovokasi, melaporkan akun penyebar, dan menggerakkan tokoh lintas suku untuk menyerukan persatuan", s:5},{t:"Mengimbau warga tenang", s:4},{t:"Diam menunggu reda", s:3},{t:"Membiarkan karena di media sosial", s:2},{t:"Ikut menyebar ujaran kebencian", s:1}], ex:"Ujaran kebencian dilawan dengan imbauan persatuan, pelaporan, dan keteladanan tokoh lintas kelompok."},
{id:"TKP-1436", q:"Ditemukan pamflet berisi ajakan memusuhi pemerintah yang sah di masjid desa. Anda akan ....", opts:[{t:"Mengamankan pamflet sebagai barang bukti dan melaporkannya ke aparat berwenang", s:5},{t:"Membuang pamflet itu", s:4},{t:"Membiarkan", s:3},{t:"Membagikan pamflet ke warga lain", s:2},{t:"Menempel pamflet di tempat lebih ramai", s:1}], ex:"Materi hasutan terhadap pemerintah yang sah diamankan dan dilaporkan, bukan disebar atau didiamkan."},
{id:"TKP-1437", q:"Seorang pemuda desa terlihat mulai tertutup, memusuhi tradisi lokal, dan mengunggah konten ekstrem. Orang tuanya meminta saran Anda. Anda akan ....", opts:[{t:"Menyarankan pendekatan persuasif keluarga, melibatkan tokoh agama moderat, dan berkordinasi dengan aparat bila mengkhawatirkan", s:5},{t:"Menyarankan orang tua menasihati", s:4},{t:"Menyarankan dibiarkan saja", s:3},{t:"Mengucilkan pemuda itu", s:2},{t:"Melaporkan sebagai teroris tanpa bukti", s:1}], ex:"Gejala paparan ekstremisme ditangani dengan pembinaan persuasif melibatkan keluarga dan tokoh agama."},
{id:"TKP-1438", q:"Simbol kelompok terlarang dikibarkan dalam acara pemuda desa. Anda sebagai perangkat desa akan ....", opts:[{t:"Menegur panitia, menurunkan simbol itu, dan melaporkan kejadian ke pihak berwenang", s:5},{t:"Menegur panitia saja", s:4},{t:"Membiarkan karena tidak paham artinya", s:3},{t:"Ikut mengibarkan", s:2},{t:"Memfoto dan menyebarkannya", s:1}], ex:"Simbol kelompok terlarang wajib diturunkan dan dilaporkan; ketidaktahuan bukan alasan pembiaran."},
{id:"TKP-1439", q:"Dua ormas kepemudaan di desa Anda bersitegang dan saling provokasi hingga berpotensi bentrok. Anda akan ....", opts:[{t:"Memfasilitasi mediasi kedua pimpinan ormas dengan melibatkan tokoh masyarakat dan aparat keamanan", s:5},{t:"Meminta keduanya menahan diri", s:4},{t:"Membiarkan hingga reda", s:3},{t:"Memihak ormas yang lebih besar", s:2},{t:"Memprovokasi salah satu pihak", s:1}], ex:"Potensi konflik horizontal diredam dengan mediasi yang melibatkan semua pihak terkait."},
{id:"TKP-1440", q:"Balai desa diminta dipakai untuk kegiatan yang diduga menyebarkan paham intoleran. Anda akan ....", opts:[{t:"Menolak pemakaian dan menjelaskan bahwa fasilitas negara tidak boleh dipakai untuk kegiatan yang merusak persatuan", s:5},{t:"Menolak tanpa penjelasan", s:4},{t:"Mengizinkan dengan pengawasan", s:3},{t:"Mengizinkan karena penyewa membayar", s:2},{t:"Ikut serta dalam kegiatan itu", s:1}], ex:"Fasilitas publik tidak boleh menjadi sarana penyebaran paham yang merusak persatuan bangsa."},
];